/stdlib/math.goose:
// The Goose standard library: `math` (docs/stdlib.md): libm, declared once
// per function and float width (spec §7.10), plus the constants and
// conversions that need no C. floor/ceil/round/trunc return floats, as in C;
// `as i64` converts. Float `%` is already fmod (§6.1). sqrt is the runtime's
// (runtime_ext.h), which has no errno to set and so compiles to the bare
// square root instruction where the C compiler allows. The functions C has
// set errno are libm's under the runtime's names, which tell the C compiler
// they depend on their arguments alone (Goose has no errno).

extern "gs_sqrt" fn sqrt(x: f64) -> f64;            extern "gs_sqrtf" fn sqrt(x: f32) -> f32;
extern "gs_sin" fn sin(x: f64) -> f64;              extern "gs_sinf" fn sin(x: f32) -> f32;
extern "gs_cos" fn cos(x: f64) -> f64;              extern "gs_cosf" fn cos(x: f32) -> f32;
extern "gs_tan" fn tan(x: f64) -> f64;              extern "gs_tanf" fn tan(x: f32) -> f32;
extern "gs_asin" fn asin(x: f64) -> f64;            extern "gs_asinf" fn asin(x: f32) -> f32;
extern "gs_acos" fn acos(x: f64) -> f64;            extern "gs_acosf" fn acos(x: f32) -> f32;
extern "gs_atan" fn atan(x: f64) -> f64;            extern "gs_atanf" fn atan(x: f32) -> f32;
extern "gs_atan2" fn atan2(y: f64, x: f64) -> f64;  extern "gs_atan2f" fn atan2(y: f32, x: f32) -> f32;
extern "gs_exp" fn exp(x: f64) -> f64;              extern "gs_expf" fn exp(x: f32) -> f32;
extern "gs_log" fn log(x: f64) -> f64;              extern "gs_logf" fn log(x: f32) -> f32;
extern "gs_log2" fn log2(x: f64) -> f64;            extern "gs_log2f" fn log2(x: f32) -> f32;
extern "gs_log10" fn log10(x: f64) -> f64;          extern "gs_log10f" fn log10(x: f32) -> f32;
extern "gs_pow" fn pow(x: f64, y: f64) -> f64;      extern "gs_powf" fn pow(x: f32, y: f32) -> f32;
extern fn floor(x: f64) -> f64;                     extern "floorf" fn floor(x: f32) -> f32;
extern fn ceil(x: f64) -> f64;                      extern "ceilf" fn ceil(x: f32) -> f32;
extern fn round(x: f64) -> f64;                     extern "roundf" fn round(x: f32) -> f32;
extern fn trunc(x: f64) -> f64;                     extern "truncf" fn trunc(x: f32) -> f32;

let PI = 3.141592653589793;
let TAU = 6.283185307179586;

fn radians(deg: f64) -> f64 { deg * (PI / 180.0) }
fn degrees(rad: f64) -> f64 { rad * (180.0 / PI) }

fn is_nan(x: f64) -> bool { x != x }
fn is_inf(x: f64) -> bool { x == x && (x - x) != (x - x) }

/stdlib/os.goose:
// The Goose standard library: `os` (docs/stdlib.md): a thin layer over the
// C in src/runtime/runtime_os.h (spec §7.10) -- enough to write tools and
// benchmarks. Text goes into builders the caller passes (§2.2 of the
// design); two-outcome calls return a trailing bool.

import std;

// Files. Paths are UTF-8 everywhere, Windows included.
extern "gs_os_read_file" fn read_file(path: const u8[:], out: u8[>..]&) -> bool;      // appends the whole file
extern "gs_os_write_file" fn write_file(path: const u8[:], data: const u8[:]) -> bool;
// All or nothing: a new file beside `path`, flushed to disk and renamed over it.
extern "gs_os_write_file_atomic" fn write_file_atomic(path: const u8[:], data: const u8[:]) -> bool;
extern "gs_os_append_file" fn append_file(path: const u8[:], data: const u8[:]) -> bool;
extern "gs_os_file_exists" fn file_exists(path: const u8[:]) -> bool;      // a file, not a directory
extern "gs_os_remove_file" fn delete_file(path: const u8[:]) -> bool;
// Replaces `to`, if there is one, in a single step.
extern "gs_os_rename_file" fn rename_file(from: const u8[:], to: const u8[:]) -> bool;

// Directories.
extern "gs_os_make_dir" fn make_dir(path: const u8[:]) -> bool;           // true if one is there afterwards
extern "gs_os_is_dir" fn is_dir(path: const u8[:]) -> bool;
extern "gs_os_remove_dir" fn delete_dir(path: const u8[:]) -> bool;       // an empty one
// Appends each entry's name and a '\n', sorted bytewise, "." and ".." left out.
extern "gs_os_list_dir" fn list_dir(path: const u8[:], out: u8[>..]&) -> bool;

// Standard streams.
extern "gs_os_read_line" fn read_line(out: u8[>..]&) -> bool;    // one line of stdin, no newline; false at end
extern "gs_os_read_stdin" fn read_stdin(out: u8[>..]&);          // everything until end of input
extern "gs_os_write_stdout" fn write_stdout(s: const u8[:]);
extern "gs_os_write_stderr" fn write_stderr(s: const u8[:]);
extern "gs_os_flush_stdout" fn flush_stdout();

// Arguments and environment.
extern "gs_os_arg_count" fn arg_count() -> i64;
extern "gs_os_arg" fn arg(i: i64, out: u8[>..]&);              // appends argument i (0 = the program)
extern "gs_os_getenv" fn env(name: const u8[:], out: u8[>..]&) -> bool;

// Application resources: the entry source's directory in JIT, the executable's
// directory in AOT (Contents/Resources/ in a macOS .app). Absolute UTF-8 with
// a trailing separator, ready to concatenate. Ordinary file paths still use cwd.
// The builder form appends nothing on failure; the string form aborts on failure.
extern "gs_os_resource_dir" fn resource_dir(out: u8[>..]&) -> bool;
fn resource_dir() -> u8[>..] {
    var out: u8[>..] = [];
    if !resource_dir(out) { abort("cannot locate the application resource directory"); }
    return out;
}

// The bytes behind args(): grow-only, so the slices handed out stay valid
// however many times it is called.
var argv_text: u8[>..] = [];

fn args() -> u8[:][>..] {
    var out: u8[:][>..] = [];
    for i in arg_count() {
        let start = argv_text.len;
        arg(i, argv_text);
        out.push(argv_text[start..]);
    }
    return out;
}

// Time.
extern "gs_os_time_ns" fn time_ns() -> i64;      // wall clock, nanoseconds since the epoch
extern "gs_os_clock_ns" fn clock_ns() -> i64;    // monotonic, high resolution
extern "gs_os_sleep_ms" fn sleep_ms(ms: i64);

// A nanosecond count past 2^53 rounds to the nearest f64. A sleep is whole
// milliseconds, truncated: `as!`, since that drops the fraction on purpose.
fn time() -> f64 { time_ns() / 1000000000.0 }
fn clock() -> f64 { clock_ns() / 1000000000.0 }
fn sleep(seconds: f64) { sleep_ms((seconds * 1000.0) as! i64) }

// Entropy, for seeding an rng.
extern "gs_os_random_u64" fn random_seed() -> u64;

/stdlib/regex.goose:
// Regular expressions (docs/stdlib.md), with the syntax and the semantics of
// the Rust `regex` crate: leftmost-first matching (the earliest match wins,
// and among the matches starting there the alternatives and repetitions are
// preferred in pattern order, `*?` and friends being lazy), unanchored
// search, and non-overlapping iteration.
//
// A pattern is parsed into a syntax tree and compiled to a Thompson NFA, the
// program, built in the shapes the crate's compiler builds, on which the
// order of preference depends. From it `compile` builds complete DFAs once,
// up front: a forward one, which finds where the leftmost-first match ends,
// and one over the reversed pattern, which walks back from that end to
// where the match starts. A search is then one table lookup per byte, and
// whenever the forward DFA is back in its start state a skip loop passes
// over the text where no match can start: one that tests two of the
// leading bytes every match has, or one that looks for a rare byte inside
// every match and walks back from it. Capture groups, which a DFA cannot
// see, come from their fixed places in the match where the pattern gives
// them one, and from a backtracker that runs over the match alone where not.
//
// The engine works on bytes: classes, `\d`, `\w`, `\s` and case folding are
// ASCII, which is what the crate's Unicode classes come to on ASCII text.
// Not supported: anchors and word boundaries (`^ $ \A \z \b \B`), class
// set operations, and patterns too large to compile: whose programs would
// need more than MAX_INSTS instructions, or whose DFAs more than MAX_STATES
// states or more than MAX_WORK steps to build.
//
// Known differences: the crate factors a prefix that every alternative
// shares out of an alternation, `a*ab|a*c?` becoming `a*(?:ab|c?)`, which
// changes the leftmost-first match where that prefix can repeat (on "aab"
// the crate matches "aa"); here the pattern means what it says, as in Perl
// and RE2. And where the last groups of a pattern lie under a `{0}`, the
// crate leaves them out of a match's groups, where here they are there and
// take no part.

namespace regex;

import std;
import dictionary;

let MAX_STATES = 10000;     // per DFA
let MAX_WORK = 50000000;    // per DFA: its states' threads times its columns
let MAX_INSTS = 10000;      // per program
let MAX_PREFIX = 8;         // leading byte positions the prefix test considers
let MAX_REPEAT = 1000;      // the largest count a {n,m} may give

// --- the syntax tree ---------------------------------------------------------

// A node of the parsed pattern; children are indices into the node pool.
enum Node {
    Empty,
    Bytes { set: i32 },                                     // one byte of the set
    Cat { first: i32, second: i32 },
    Alt { first: i32, second: i32 },                        // first preferred
    Repeat { sub: i32, min: i32, max: i32, greedy: bool },  // max -1: unbounded
    Group { sub: i32, index: i32 },                         // a capture group
}

// --- the program ---------------------------------------------------------------

// An NFA instruction. A program is built back to front, from the match
// instruction at 0, so an instruction's successors are already in place
// when it is added; a loop patches its head afterwards.
enum Inst {
    Byte { set: i32, next: i32 },           // consume one byte of the set
    Split { first: i32, second: i32 },      // fork; the first thread is preferred
    Save { slot: i32, next: i32 },          // record the position in a capture slot
    Match,
}

// A DFA over byte classes. States are numbered with the dead state first,
// then the match states, then, where a skip strategy takes over there, the
// start state, so a single comparison against `special` finds every state
// the search loop must look at. A state number is premultiplied by the
// number of classes: it is the offset of the state's row in `trans`.
struct Dfa { start: i32, match_end: i32, special: i32, trans: i32[] }

// How a search gets past text where no match can start, whenever the
// forward DFA is in its start state: by the prefix test, by the inner byte,
// or not at all.
enum Skip { Scan, Prefix, Inner }

// The prefix test: every match is at least `len` bytes long, and its bytes
// at offsets `at1` and `at2` lie in `set1` and `set2`, so a match can only
// start where both hold. at1 <= at2.
struct Prefilter { len: i64, at1: i64, at2: i64, set1: ByteSet, set2: ByteSet }

// Where a capture group lies in every match, if that is fixed: its start
// `start` bytes after the start of the match, or before its end with
// `start_back`, and likewise its end; -1 if not fixed.
struct Place { start: i64, start_back: bool, end: i64, end_back: bool }

struct Regex {
    groups: i64,            // capture groups, group 0 being the whole match
    nullable: bool,         // whether the empty string matches
    placed: bool,           // whether every group has a fixed place
    entry: i32,             // where the program starts an anchored match
    classes: u8[256],       // byte -> its column in the DFAs
    skip: Skip,
    filter: Prefilter,
    // The inner byte: every match has a byte of `inner` right after a part
    // that holds none, so a match can only start where the reverse DFA of
    // that part, `before`, run back from such a byte, matches.
    inner: ByteSet,
    fwd: Dfa,               // unanchored and leftmost-first: finds match ends
    rev: Dfa,               // the reversed pattern, anchored: finds match starts
    before: Dfa,
    places: Place[],
    prog: Inst[],
    sets: (bool[256])[],
}

// --- byte sets -----------------------------------------------------------------

fn add_range(s: bool[256]&, lo: u8, hi: u8) {
    for b in (lo as i64)..(hi as i64) + 1 { s[b] = true; }
}

fn is_letter(b: u8) -> bool { (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z') }

// Adds the other case of every ASCII letter in the set.
fn fold_case(s: bool[256]&) {
    for b in ('A' as i64)..('Z' as i64) + 1 {
        let lower = b + 32;
        if s[b] || s[lower] { s[b] = true; s[lower] = true; }
    }
}

// The set of \d, \w or \s (named by the escape letter's lower case), or of
// their complements \D, \W and \S, added to s. False for any other letter.
fn add_perl_class(s: bool[256]&, c: u8) -> bool {
    var t: bool[256] = [false; 256];
    let lower = if c >= 'A' && c <= 'Z' { c + 32 } else { c };
    if lower == 'd' {
        add_range(t, '0', '9');
    } else if lower == 'w' {
        add_range(t, 'a', 'z');
        add_range(t, 'A', 'Z');
        add_range(t, '0', '9');
        t['_'] = true;
    } else if lower == 's' {
        add_range(t, '\t', '\r');       // \t \n \v \f \r
        t[' '] = true;
    } else {
        return false;
    }
    let negated = c != lower;
    for b in 256 { if t[b] != negated { s[b] = true; } }
    return true;
}

// The byte a one-character escape stands for: a control character, or an
// ASCII punctuation character taken literally. -1 for anything else.
fn escaped_byte(c: u8) -> i64 {
    if c == 'n' { return '\n'; }
    if c == 't' { return '\t'; }
    if c == 'r' { return '\r'; }
    if c == 'f' { return 0x0c; }
    if c == 'v' { return 0x0b; }
    if c >= 0x21 && c < 0x7f && !is_letter(c) && !(c >= '0' && c <= '9') { return c; }
    return -1;
}

fn hex_value(c: u8) -> i64 {
    if c >= '0' && c <= '9' { return c - '0'; }
    if c >= 'a' && c <= 'f' { return c - 'a' + 10; }
    if c >= 'A' && c <= 'F' { return c - 'A' + 10; }
    return -1;
}

// --- compiling -------------------------------------------------------------------

// Compiles a pattern. A syntax error, or a pattern too large to compile,
// aborts with a message saying what and where, as unwrapping the crate's
// Regex::new would.
fn compile(pattern: u8[:]) -> Regex {
    var err: u8[>..] = [];
    return build(pattern, err, true);
}

// Compiles a pattern that may be malformed: a syntax error, or a pattern too
// large to compile, appends its message to `err` and gives a regex that
// matches nothing.
fn compile(pattern: u8[:], err: u8[>..]&) -> Regex { build(pattern, err, false) }

// A regex that matches nothing, as compile gives for a malformed pattern:
// its forward DFA starts in the dead state.
fn nothing() -> Regex {
    let dead = Dfa { start: 0, match_end: 1, special: 1, trans: [0] };
    let none: ByteSet = byte_set([false; 256]);
    return Regex {
        groups: 1, nullable: false, placed: false, entry: 0, classes: [0; 256], skip: Skip.Scan,
        filter: Prefilter { len: 0, at1: 0, at2: 0, set1: none, set2: none }, inner: none,
        fwd: dead, rev: dead, before: dead, places: [], prog: [Inst.Match], sets: [],
    };
}

fn build(pattern: u8[:], err: u8[>..]&, aborts: bool) -> Regex {
    var nodes: Node[>..] = [];
    var sets: (bool[256])[>..] = [];
    var pos = 0;
    var fold = false;           // (?i): letters match either case
    var dot_nl = false;         // (?s): `.` matches a newline too
    var groups = 1;

    // Ends the compile at an error: aborts with the message where `aborts`
    // says so, and otherwise appends it to `err` and returns a regex that
    // matches nothing. The result type lets the parsing functions return it.
    fn stop(message: u8[:]) -> i32 {
        if aborts { abort(message); }
        err.append(message);
        return nothing() from build;
    }
    fn fail_at(what: u8[:], at: i64) -> i32 { stop(str("regex: ", what, " at offset ", at, " in ", pattern)) }
    fn fail(what: u8[:]) -> i32 { fail_at(what, pos) }

    fn add(n: Node) -> i32 {
        nodes.push(n);
        return (nodes.len - 1) as i32;
    }

    fn add_bytes(s: bool[256]) -> i32 {
        sets.push(s);
        return add(Node.Bytes { set: (sets.len - 1) as i32 });
    }

    fn more() -> bool { pos < pattern.len }

    fn literal(c: u8) -> i32 {
        var s: bool[256] = [false; 256];
        s[c] = true;
        if fold { fold_case(s); }
        return add_bytes(s);
    }

    // A decimal count of a repetition.
    fn number() -> i32 {
        let start = pos;
        var v = 0;
        while more() && pattern[pos] >= '0' && pattern[pos] <= '9' {
            v = v * 10 + (pattern[pos] - '0');
            guard v <= MAX_REPEAT else { return fail("repetition count too large"); }
            pos++;
        }
        guard pos > start else { return fail("expected a repetition count"); }
        return v as i32;
    }

    // The byte of an escape whose backslash is behind us, \xNN included.
    // Errors name the backslash.
    fn escape_byte() -> u8 {
        let at = pos - 1;
        guard more() else { return fail_at("trailing backslash", at) as! u8; }
        let c = pattern[pos];
        pos++;
        if c == 'x' {
            guard pos + 2 <= pattern.len && hex_value(pattern[pos]) >= 0 && hex_value(pattern[pos + 1]) >= 0 else {
                return fail_at("bad \\x escape", at) as! u8;
            }
            let v = hex_value(pattern[pos]) * 16 + hex_value(pattern[pos + 1]);
            pos += 2;
            return v as u8;
        }
        let b = escaped_byte(c);
        guard b >= 0 else { return fail_at("unsupported escape", at) as! u8; }
        return b as u8;
    }

    // A class, its `[` behind us: bytes, ranges and Perl classes, maybe
    // negated. A `]` first, or a `-` first or last, is literal.
    fn class() -> i32 {
        var s: bool[256] = [false; 256];
        var negated = false;
        if more() && pattern[pos] == '^' { negated = true; pos++; }
        var first = true;
        loop {
            guard more() else { return fail("unclosed class"); }
            let c = pattern[pos];
            if c == ']' && !first { pos++; break; }
            first = false;
            guard c != '[' else { return fail("nested classes are not supported"); }
            guard !((c == '&' || c == '-' || c == '~') && pos + 1 < pattern.len && pattern[pos + 1] == c) else {
                return fail("class set operations are not supported");
            }
            pos++;
            var lo = c;
            if c == '\\' {
                if more() && add_perl_class(s, pattern[pos]) { pos++; continue; }
                lo = escape_byte();
            }
            if pos + 1 < pattern.len && pattern[pos] == '-' && pattern[pos + 1] != ']' {
                pos++;
                guard pattern[pos] != '-' else { return fail("class set operations are not supported"); }
                var hi = pattern[pos];
                pos++;
                if hi == '\\' { hi = escape_byte(); }
                guard hi >= lo else { return fail("bad class range"); }
                add_range(s, lo, hi);
            } else {
                s[lo] = true;
            }
        }
        if fold { fold_case(s); }
        if negated { for &x in s { x = !x; } }
        return add_bytes(s);
    }

    // An escape outside a class.
    fn escape() -> i32 {
        var s: bool[256] = [false; 256];
        if more() && add_perl_class(s, pattern[pos]) {
            pos++;
            return add_bytes(s);
        }
        return literal(escape_byte());
    }

    // A group, its `(` behind us: capturing, non-capturing `(?:...)`, with
    // flags `(?i:...)`, or a bare flag setting `(?i)`, which holds to the end
    // of the group around it.
    recursive fn group() -> i32 {
        let outer_fold = fold;
        let outer_dot = dot_nl;
        var index = -1;
        if more() && pattern[pos] == '?' {
            pos++;
            if more() && (pattern[pos] == '<' || pattern[pos] == 'P') {
                // a named group: the name does not matter here
                while more() && pattern[pos] != '>' { pos++; }
                guard more() else { return fail("unclosed group name"); }
                pos++;
                index = groups;
                groups++;
            } else {
                var on = true;
                loop {
                    guard more() else { return fail("unclosed group"); }
                    let c = pattern[pos];
                    pos++;
                    if c == ')' { return add(Node.Empty); }
                    if c == ':' { break; }
                    if c == '-' { on = false; }
                    else if c == 'i' { fold = on; }
                    else if c == 's' { dot_nl = on; }
                    else { return fail_at("unsupported flag", pos - 1); }
                }
            }
        } else {
            index = groups;
            groups++;
        }
        let body = parse_alt();
        guard more() && pattern[pos] == ')' else { return fail("unclosed group"); }
        pos++;
        fold = outer_fold;
        dot_nl = outer_dot;
        if index < 0 { return body; }
        return add(Node.Group { sub: body, index: index as i32 });
    }

    recursive fn parse_atom() -> i32 {
        let c = pattern[pos];
        guard c != '*' && c != '+' && c != '?' && c != '{' else { return fail("nothing to repeat"); }
        guard c != '^' && c != '$' else { return fail("anchors are not supported"); }
        pos++;
        if c == '(' { return group(); }
        if c == '[' { return class(); }
        if c == '\\' { return escape(); }
        if c == '.' {
            var s: bool[256] = [true; 256];
            if !dot_nl { s['\n'] = false; }
            return add_bytes(s);
        }
        return literal(c);
    }

    // An atom and the repetition operators after it.
    recursive fn parse_repeat() -> i32 {
        var sub = parse_atom();
        while more() {
            let c = pattern[pos];
            var min: i32 = 0;
            var max: i32 = -1;
            if c == '*' {
                pos++;
            } else if c == '+' {
                min = 1;
                pos++;
            } else if c == '?' {
                max = 1;
                pos++;
            } else if c == '{' {
                pos++;
                min = number();
                max = min;
                if more() && pattern[pos] == ',' {
                    pos++;
                    max = if more() && pattern[pos] == '}' { -1 } else { number() };
                }
                guard more() && pattern[pos] == '}' else { return fail("unclosed repetition"); }
                guard max < 0 || max >= min else { return fail("bad repetition range"); }
                pos++;
            } else {
                break;
            }
            var greedy = true;
            if more() && pattern[pos] == '?' { greedy = false; pos++; }
            sub = add(Node.Repeat { sub: sub, min: min, max: max, greedy: greedy });
        }
        return sub;
    }

    recursive fn parse_cat() -> i32 {
        var seq = -1;
        while more() && pattern[pos] != '|' && pattern[pos] != ')' {
            let item = parse_repeat();
            seq = if seq < 0 { item } else { add(Node.Cat { first: seq as i32, second: item }) };
        }
        if seq < 0 { return add(Node.Empty); }
        return seq as i32;
    }

    recursive fn parse_alt() -> i32 {
        let first = parse_cat();
        if more() && pattern[pos] == '|' {
            pos++;
            let second = parse_alt();
            return add(Node.Alt { first: first, second: second });
        }
        return first;
    }

    fn push(prog: Inst[>..]&, i: Inst) -> i32 {
        if prog.len >= MAX_INSTS { stop(str("regex: the pattern is too large: ", pattern)); }
        prog.push(i);
        return (prog.len - 1) as i32;
    }

    // A repetition's choice between another round of `body` and leaving.
    fn choice(greedy: bool, body: i32, exit: i32) -> Inst {
        if greedy { Inst.Split { first: body, second: exit } } else { Inst.Split { first: exit, second: body } }
    }

    // Whether node n can match the empty string.
    recursive fn nullable(n: i32) -> bool {
        match nodes[n] {
            Empty => true,
            Bytes => false,
            Cat c => nullable(c.first) && nullable(c.second),
            Alt a => nullable(a.first) || nullable(a.second),
            Group g => nullable(g.sub),
            Repeat r => r.min == 0 || nullable(r.sub),
        }
    }

    // Node n's instructions, continuing at `next`; returns their entry. The
    // reversed program matches the reversed strings and records no groups.
    recursive fn emit(prog: Inst[>..]&, n: i32, next: i32, reverse: bool) -> i32 {
        match nodes[n] {
            Empty => { return next; },
            Bytes b => { return push(prog, Inst.Byte { set: b.set, next: next }); },
            Cat c => {
                if reverse { return emit(prog, c.second, emit(prog, c.first, next, reverse), reverse); }
                return emit(prog, c.first, emit(prog, c.second, next, reverse), reverse);
            },
            Alt a => {
                let first = emit(prog, a.first, next, reverse);
                let second = emit(prog, a.second, next, reverse);
                return push(prog, Inst.Split { first: first, second: second });
            },
            Group g => {
                if reverse { return emit(prog, g.sub, next, reverse); }
                let close = push(prog, Inst.Save { slot: 2 * g.index + 1, next: next });
                let body = emit(prog, g.sub, close, reverse);
                return push(prog, Inst.Save { slot: 2 * g.index, next: body });
            },
            // The shapes the regex crate's compiler gives repetitions: which
            // thread a leftmost-first match prefers depends on them where the
            // repeated expression can match the empty string.
            Repeat r => {
                var t = next;
                if r.max >= 0 {
                    // x{2,4} is xx(x(x)?)?
                    for k in r.max - r.min {
                        t = push(prog, choice(r.greedy, emit(prog, r.sub, t, reverse), next));
                    }
                    for k in r.min { t = emit(prog, r.sub, t, reverse); }
                    return t;
                }
                // x{n,} is x{n-1} and then x looping back to itself; x* is a
                // loop, or (x+)? where x can match the empty string.
                let head = push(prog, Inst.Match);      // patched below
                let body = emit(prog, r.sub, head, reverse);
                prog[head] = choice(r.greedy, body, next);
                if r.min == 0 {
                    if nullable(r.sub) { return push(prog, choice(r.greedy, body, next)); }
                    return head;
                }
                t = body;
                for k in r.min - 1 { t = emit(prog, r.sub, t, reverse); }
                return t;
            },
        }
    }

    // The length every match of node n has, or -1 if it varies.
    recursive fn fixed_len(n: i32) -> i64 {
        match nodes[n] {
            Empty => 0,
            Bytes => 1,
            Cat c => {
                let a = fixed_len(c.first);
                let b = fixed_len(c.second);
                if a < 0 || b < 0 { -1 } else { a + b }
            },
            Alt a => {
                let x = fixed_len(a.first);
                if x == fixed_len(a.second) { x } else { -1 }
            },
            Repeat r => {
                let x = fixed_len(r.sub);
                if r.min == r.max && x >= 0 { x * r.min } else { -1 }
            },
            Group g => fixed_len(g.sub),
        }
    }

    // Adds every byte node n can consume to s.
    recursive fn alphabet(n: i32, s: bool[256]&) {
        match nodes[n] {
            Empty => {},
            Bytes b => { for c in 256 { if sets[b.set][c] { s[c] = true; } } },
            Cat c => { alphabet(c.first, s); alphabet(c.second, s); },
            Alt a => { alphabet(a.first, s); alphabet(a.second, s); },
            Repeat r => { if r.max != 0 { alphabet(r.sub, s); } },
            Group g => { alphabet(g.sub, s); },
        }
    }

    // Adds the bytes a match of node n can start with to s; true if it can
    // be empty, so that what follows it can start the match as well.
    recursive fn first_bytes(n: i32, s: bool[256]&) -> bool {
        match nodes[n] {
            Empty => true,
            Bytes b => {
                for c in 256 { if sets[b.set][c] { s[c] = true; } }
                false
            },
            Cat c => if first_bytes(c.first, s) { first_bytes(c.second, s) } else { false },
            Alt a => {
                let x = first_bytes(a.first, s);
                let y = first_bytes(a.second, s);
                x || y
            },
            Repeat r => {
                if r.max == 0 { return true; }
                let empty = first_bytes(r.sub, s);
                empty || r.min == 0
            },
            Group g => first_bytes(g.sub, s),
        }
    }

    // The nodes a concatenation is made of, in order.
    recursive fn flatten(n: i32, out: i32[>..]&) {
        match nodes[n] {
            Cat c => { flatten(c.first, out); flatten(c.second, out); },
            _ => { out.push(n); },
        }
    }

    // Records the place of each group that every match of node n holds at
    // a fixed distance from the match's ends: n spans the match but for
    // `head` bytes at its start and `tail` at its end, each -1 if unknown.
    // Groups under an alternation or a repetition are left out: they need
    // not take part in a match, or take part more than once.
    recursive fn place(n: i32, head: i64, tail: i64, places: Place[>..]&) {
        match nodes[n] {
            Cat c => {
                let a = fixed_len(c.first);
                let b = fixed_len(c.second);
                place(c.first, head, if tail >= 0 && b >= 0 { tail + b } else { -1 }, places);
                place(c.second, if head >= 0 && a >= 0 { head + a } else { -1 }, tail, places);
            },
            Group g => {
                let len = fixed_len(g.sub);
                var p = Place { start: -1, start_back: false, end: -1, end_back: false };
                if head >= 0 {
                    p.start = head;
                } else if tail >= 0 && len >= 0 {
                    p.start = tail + len;
                    p.start_back = true;
                }
                if tail >= 0 {
                    p.end = tail;
                    p.end_back = true;
                } else if head >= 0 && len >= 0 {
                    p.end = head + len;
                }
                places[g.index] = p;
                place(g.sub, head, tail, places);
            },
            _ => {},
        }
    }

    let root = parse_alt();
    if more() { fail("unmatched )"); }

    var prog: Inst[>..] = [];
    var rprog: Inst[>..] = [];
    let top = add(Node.Group { sub: root, index: 0 });
    let entry = emit(prog, top, push(prog, Inst.Match), false);
    let rentry = emit(rprog, root, push(rprog, Inst.Match), true);

    // The unanchored start: (?s:.)*? ahead of the pattern, lowest priority.
    sets.push([true; 256]);
    let head = push(prog, Inst.Match);
    let any = push(prog, Inst.Byte { set: (sets.len - 1) as i32, next: head });
    prog[head] = Inst.Split { first: entry, second: any };

    // The prefix test, and the inner byte: of the sets of bytes that can
    // start the rest of the pattern after a leading part of its
    // concatenation, the rarest one the leading part cannot consume.
    let prefix = prefix_sets(prog, sets, entry);
    let filter, filter_share = choose_filter(prefix);
    var items: i32[>..] = [];
    flatten(root, items);
    var inner: bool[256] = [false; 256];
    var inner_share = 1.0;
    var inner_at = -1;
    for t in 1..items.len {
        var before: bool[256] = [false; 256];
        for k in t { alphabet(items[k], before); }
        var start: bool[256] = [false; 256];
        var empty = true;
        for k in t..items.len {
            if !first_bytes(items[k], start) { empty = false; break; }
        }
        var share = 0.0;
        var disjoint = !empty;
        for c in 256 {
            if start[c] {
                share += frequency(c as u8) / 100.0;
                if before[c] { disjoint = false; }
            }
        }
        if disjoint && share < inner_share { inner = start; inner_share = share; inner_at = t; }
    }
    // A skip loop pays where it lets through under a tenth of the
    // positions; the inner byte, each of whose hits costs a backward scan,
    // is taken only where it is several times rarer than the prefix test.
    var skip = Skip.Scan;
    var bprog: Inst[>..] = [];
    var bentry = push(bprog, Inst.Match);
    if prefix.len > 0 && inner_at > 0 && inner_share < 0.1 && inner_share * 4.0 < filter_share {
        skip = Skip.Inner;
        var part = items[0];
        for k in 1..inner_at { part = add(Node.Cat { first: part, second: items[k] }); }
        bentry = emit(bprog, part, bentry, true);
    } else if filter_share < 0.1 {
        skip = Skip.Prefix;
    }

    var places: Place[>..] = [];
    places.resize(groups, Place { start: -1, start_back: false, end: -1, end_back: false });
    place(top, 0, 0, places);
    var placed = true;
    for p in places { if p.start < 0 || p.end < 0 { placed = false; } }

    let classes = byte_classes(sets);
    let scans = skip != Skip.Scan;
    var too_big = false;
    let re = Regex {
        groups: groups,
        nullable: prefix.len == 0,
        placed: placed,
        entry: entry,
        classes: classes,
        skip: skip,
        filter: filter,
        inner: byte_set(inner),
        fwd: build_dfa(prog, sets, classes, head, true, scans, too_big),
        rev: build_dfa(rprog, sets, classes, rentry, false, false, too_big),
        before: build_dfa(bprog, sets, classes, bentry, false, false, too_big),
        places: copy(places),
        prog: copy(prog),
        sets: copy(sets),
    };
    if too_big { stop(str("regex: the pattern's DFA would be too large: ", pattern)); }
    return re;
}

// --- analysis --------------------------------------------------------------------

// The bytes each of a match's leading positions can hold: element j is the
// set of bytes at offset j, for every offset a match always reaches (up to
// MAX_PREFIX of them). Empty when the empty string matches.
fn prefix_sets(prog: Inst[:], sets: (bool[256])[:], entry: i32) -> (bool[256])[>..] {
    var out: (bool[256])[>..] = [];
    var front: i32[>..] = [];       // the Byte instructions a thread can be at
    var next: i32[>..] = [];
    var seen: i32[>..] = [];
    seen.resize(prog.len, -1);
    var round: i32 = 0;
    var stack: i32[>..<] = [];

    // Adds the Byte instructions pc leads to without consuming a byte to
    // `next`; true if it can reach a match that way.
    fn reach(pc0: i32) -> bool {
        var matched = false;
        stack.push(pc0);
        while stack.len > 0 {
            let pc = stack.pop();
            if seen[pc] == round { continue; }
            seen[pc] = round;
            match prog[pc] {
                Byte => next.push(pc),
                Split sp => { stack.push(sp.second); stack.push(sp.first); },
                Save sv => stack.push(sv.next),
                Match => { matched = true; },
            }
        }
        return matched;
    }

    if reach(entry) { return out; }
    while out.len < MAX_PREFIX {
        front.clear();
        front.append(next);
        next.clear();
        round++;
        var s: bool[256] = [false; 256];
        var matched = false;
        for pc in front {
            match prog[pc] {
                Byte b => {
                    for c in 256 { if sets[b.set][c] { s[c] = true; } }
                    if reach(b.next) { matched = true; }
                },
                _ => {},
            }
        }
        out.push(s);
        if matched { break; }
    }
    return out;
}

// A rough share, in percent, of a byte in typical text, prose, code and
// data alike: the digits rank with the letters, as in the byte-frequency
// table the regex crate picks its prefilter bytes by.
fn frequency(b: u8) -> f64 {
    if b == ' ' { return 15.0; }
    if b >= 'a' && b <= 'z' { return if position("etaoinsrhl", b) >= 0 { 5.0 } else { 1.0 }; }
    if b >= '0' && b <= '9' { return 2.0; }
    if b >= 'A' && b <= 'Z' { return 0.5; }
    if b == '\n' || position(""".,-/:;"'()=_""", b) >= 0 { return 1.0; }
    if b > ' ' && b < 0x7f { return 0.2; }
    return 0.05;
}

// The prefix test for these prefix sets: the pair of positions, or the one
// position, whose bytes are rarest by `frequency`, and the share of
// positions it is expected to let through.
fn choose_filter(prefix: (bool[256])[:]) -> Prefilter, f64 {
    var share: f64[>..] = [];
    for &s in prefix {
        var f = 0.0;
        for b in 256 { if s[b] { f += frequency(b as u8); } }
        share.push(f / 100.0);
    }
    var best = 1.0;
    var at1 = 0;
    var at2 = 0;
    for j in prefix.len {
        for k in j..prefix.len {
            let p = if j == k { share[j] } else { share[j] * share[k] };
            if p < best { best = p; at1 = j; at2 = k; }
        }
    }
    guard prefix.len > 0 else {
        let none = byte_set([false; 256]);
        return Prefilter { len: 0, at1: 0, at2: 0, set1: none, set2: none }, 1.0;
    }
    return Prefilter { len: prefix.len, at1: at1, at2: at2, set1: byte_set(prefix[at1]),
                       set2: byte_set(prefix[at2]) }, best;
}

// The byte classes of a program's sets: two bytes share a class when every
// set treats them alike, so a DFA needs a column per class rather than per
// byte. Classes are numbered in the order of their first byte.
fn byte_classes(sets: (bool[256])[:]) -> u8[256] {
    var classes: u8[256] = [0; 256];
    for &s in sets {
        var split: i32[512] = [-1; 512];    // (class, in s) -> refined class
        var n: i32 = 0;
        for b in 256 {
            let k = classes[b] as i64 * 2 + (if s[b] { 1 } else { 0 });
            if split[k] < 0 { split[k] = n; n++; }
            classes[b] = split[k] as u8;
        }
    }
    return classes;
}

// --- the DFAs ----------------------------------------------------------------------

// The DFA of a program, by subset construction. A state is the
// priority-ordered list of the Byte instructions its threads wait at, and
// whether a thread has matched. With `leftmost` the list ends at the first
// match, which drops every thread of lower priority, as leftmost-first
// semantics wants; without it every thread runs on, so that the reverse DFA
// sees each place a match can start. `skip_start` makes the start state
// special, for a search that hands it to a skip loop. A DFA that would be too
// large to build sets `too_big` and comes back empty.
fn build_dfa(prog: Inst[:], sets: (bool[256])[:], classes: u8[256], start_pc: i32,
             leftmost: bool, skip_start: bool, too_big: bool&) -> Dfa {
    var reps: u8[>..] = [];         // the first byte of each class
    for b in 256 { if classes[b] == reps.len { reps.push(b as u8); } }
    let stride = reps.len;

    var lists: i32[>..] = [];       // every state's instructions, back to back
    var bounds: i64[>..] = [0];     // state k's are lists[bounds[k]..bounds[k + 1]]
    var matching: bool[>..] = [];
    var keys: u8[>..] = [];         // the same lists, encoded as dictionary keys
    var index = dictionary<const u8[:], i32> {};
    var trans: i32[>..] = [];       // by state index, stride entries per state

    var list: i32[>..] = [];        // the state being made
    var matched = false;
    var probe: u8[>..] = [];
    var seen: i32[>..] = [];
    seen.resize(prog.len, -1);
    var round: i32 = 0;
    var stack: i32[>..<] = [];

    // Adds the threads pc leads to without consuming a byte, in priority
    // order; true if a match cut the list short.
    fn follow(pc0: i32) -> bool {
        stack.push(pc0);
        while stack.len > 0 {
            let pc = stack.pop();
            if seen[pc] == round { continue; }
            seen[pc] = round;
            match prog[pc] {
                Byte => list.push(pc),
                Split sp => { stack.push(sp.second); stack.push(sp.first); },
                Save sv => stack.push(sv.next),
                Match => {
                    matched = true;
                    if leftmost { stack.clear(); return true; }
                },
            }
        }
        return false;
    }

    // The state for `list` and `matched`, made if it is new.
    fn intern() -> i32 {
        probe.clear();
        for pc in list { format_uleb(probe, pc); }
        probe.push(if matched { 1 } else { 0 });
        let known = index.get(probe);
        if known { return known; }
        let id = matching.len as i32;
        let k = keys.len;
        keys.append(probe);
        index.insert(keys[k..], id);
        lists.append(list);
        bounds.push(lists.len);
        matching.push(matched);
        guard matching.len <= MAX_STATES && lists.len * stride <= MAX_WORK else {
            too_big = true;
            return Dfa { start: 0, match_end: 1, special: 1, trans: [0] } from build_dfa;
        }
        return id;
    }

    fn begin() {
        list.clear();
        matched = false;
        round++;
    }

    begin();
    intern();                       // 0: the dead state, with no threads
    begin();
    follow(start_pc);
    let start = intern();
    var k = 0;
    while k < matching.len {
        for c in stride {
            begin();
            for at in bounds[k]..bounds[k + 1] {
                match prog[lists[at]] {
                    Byte b => if sets[b.set][reps[c]] && follow(b.next) { break; },
                    _ => {},
                }
            }
            trans.push(intern());
        }
        k++;
    }

    // Renumbered: the dead state, the match states, the start state if it
    // is special, then the rest.
    var order: i32[>..] = [0];
    for s in 1..matching.len { if matching[s] { order.push(s as i32); } }
    let match_end = order.len;
    let start_special = skip_start && !matching[start];
    if start_special { order.push(start); }
    let special = order.len;
    for s in 1..matching.len {
        if !matching[s] && !(start_special && s == start) { order.push(s as i32); }
    }
    var number: i32[>..] = [];
    number.resize(order.len, 0);
    for old, new in order { number[old] = new as i32; }
    let width = stride as i32;
    var table: i32[>..] = [];
    for old in order {
        for c in stride { table.push(number[trans[old * stride + c]] * width); }
    }
    return Dfa {
        start: number[start] * width,
        match_end: match_end as i32 * width,
        special: special as i32 * width,
        trans: copy(table),
    };
}

// --- searching ----------------------------------------------------------------------

// The prefix test's next position at or after i where a match can start;
// text.len if there is none.
fn skip_prefix(f: Prefilter&, text: u8[:], i: i64) -> i64 {
    let fits = text.len - f.len + 1;    // the positions a match fits at
    assert(i >= 0);
    guard i < fits else { return text.len; }
    // The first position from i on whose bytes at1 and at2 on pass the tests.
    let p = if f.at1 == f.at2 { find_any(text[i + f.at1..fits + f.at1], f.set1) }
            else { find_pair(text[i + f.at1..fits + f.at2], f.set1, f.at2 - f.at1, f.set2) };
    return if p >= 0 { i + p } else { text.len };
}

// The inner byte's next position at or after i where a match can start:
// where the part before an inner byte starts, found by running its reverse
// DFA back from the byte, no further than i or than the inner byte before.
fn skip_inner(re: Regex&, text: u8[:], i: i64) -> i64 {
    assert(i >= 0);
    var lo = i;
    var q = i;
    while q < text.len {
        let k = find_any(text[q..], re.inner);
        if k < 0 { break; }
        q += k;
        let s = scan_back(re, re.before, text, lo, q);
        if s >= 0 { return s; }
        q++;
        lo = q;
    }
    return text.len;
}

// Where the search goes on when the forward DFA is in its start state at
// i, which no match starts before: the first position a match can start at.
fn resume(re: Regex&, text: u8[:], i: i64) -> i64 {
    match re.skip {
        Prefix => skip_prefix(re.filter, text, i),
        Inner => skip_inner(re, text, i),
        Scan => i,
    }
}

// The end of the leftmost-first match that starts at or after `at`, or -1.
fn find_end(re: Regex&, text: u8[:], at: i64) -> i64 {
    let trans = re.fwd.trans;
    let start = re.fwd.start;
    let special = re.fwd.special;
    var s = start;
    var last: i64 = -1;
    if re.nullable { last = at; }
    var i = resume(re, text, at);
    while i < text.len {
        s = trans[s + re.classes[text[i]]];
        i++;
        if s < special {
            if s >= re.fwd.match_end {
                // back at the start: no thread is alive but the search's own
                i = resume(re, text, i);
            } else if s == 0 {
                return last;
            } else {
                last = i;
            }
        }
    }
    return last;
}

// Where the reverse DFA d, run back from `end` no further than `lo`, last
// matches: the leftmost start of a match of its pattern that ends at
// `end`; -1 if there is none.
fn scan_back(re: Regex&, d: Dfa&, text: u8[:], lo: i64, end: i64) -> i64 {
    let trans = d.trans;
    let match_end = d.match_end;
    var s = d.start;
    var first: i64 = -1;
    if s < match_end { first = end; }
    assert(lo >= 0 && end <= text.len);
    var i = end;
    while i > lo {
        s = trans[s + re.classes[text[i - 1]]];
        i--;
        if s < match_end {
            if s == 0 { break; }
            first = i;
        }
    }
    return first;
}

// Where the match that ends at `end`, and starts at or after `at`, starts.
fn find_start(re: Regex&, text: u8[:], at: i64, end: i64) -> i64 { scan_back(re, re.rev, text, at, end) }

// The leftmost-first match: where it starts and where it ends; -1, -1 if
// there is none.
fn find(re: Regex&, text: u8[:]) -> i64, i64 {
    let e = find_end(re, text, 0);
    if e < 0 { return -1, -1; }
    return find_start(re, text, 0, e), e;
}

// Whether text holds a match, as the crate's is_match: the reverse DFA,
// which finds where a match starts, is not run.
fn matches(re: Regex&, text: u8[:]) -> bool { find_end(re, text, 0) >= 0 }

// F(start, end) for every match, left to right, as the regex crate's
// find_iter yields them: no two overlap, and no empty match comes where the
// previous match ended.
fn each_match<F>(re: Regex&, text: u8[:]) {
    var at = 0;
    var last_end = -1;
    while at <= text.len {
        var e = find_end(re, text, at);
        if e < 0 { break; }
        var s = find_start(re, text, at, e);
        if s == e && e == last_end {
            if at == text.len { break; }
            e = find_end(re, text, at + 1);
            if e < 0 { break; }
            s = find_start(re, text, at + 1, e);
        }
        F(s, e);
        at = e;
        last_end = e;
    }
}

// The number of matches: what find_iter(text).count() counts. A match that
// cannot be empty is counted from its end alone, as the crate's count()
// does: only a match's start takes the reverse DFA.
fn count(re: Regex&, text: u8[:]) -> i64 {
    var n = 0;
    if re.nullable {
        each_match(re, text) { s, e => n++; };
        return n;
    }
    var at = 0;
    loop {
        let e = find_end(re, text, at);
        if e < 0 { break; }
        n++;
        at = e;
    }
    return n;
}

// --- capture groups --------------------------------------------------------------------

// The capture groups of a match: group k spans slots[2k]..slots[2k + 1] of
// the text, or both are -1 if it took no part in the match. Group 0 is the
// match, and the others are numbered by their opening parentheses.
struct Captures { text: const u8[:], slots: const i64[:] }

// Group k's text; empty if the group took no part in the match.
fn group(c: Captures, k: i64) -> const u8[:] {
    let s = c.slots[2 * k];
    if s < 0 { return c.text[0..0]; }
    return c.text[s..c.slots[2 * k + 1]];
}

// A step of the backtracking search: a thread to explore, or a capture slot
// to restore when the search backs out of the thread that set it.
enum Frame { Explore { pc: i32, at: i64 }, Restore { slot: i32, old: i64 } }

// The capture slots of the leftmost-first match [start, end), by
// backtracking over the program from `start` in priority order: the first
// thread to reach the match instruction is the one the match took. Each
// (instruction, position) pair is explored once at most, which `visited`,
// the caller's scratch, records.
fn backtrack(re: Regex&, text: u8[:], start: i64, end: i64, slots: i64[:], visited: bool[>..]&) {
    let prog = re.prog;
    let sets = re.sets;
    let width = end - start + 1;
    let need = prog.len * width;
    if visited.len < need { visited.resize(need, false); }
    fill(visited[..need], false);
    var stack: Frame[>..<] = [];
    fill(slots, -1);
    stack.push(Frame.Explore { pc: re.entry, at: start });
    while stack.len > 0 {
        match stack.pop() {
            Restore r => { slots[r.slot] = r.old; },
            Explore x => {
                var pc = x.pc;
                var i = x.at;
                loop {
                    let k = pc * width + (i - start);
                    if visited[k] { break; }
                    visited[k] = true;
                    match prog[pc] {
                        Byte b => {
                            guard i < end && sets[b.set][text[i]] else { break; }
                            pc = b.next;
                            i++;
                        },
                        Split sp => {
                            stack.push(Frame.Explore { pc: sp.second, at: i });
                            pc = sp.first;
                        },
                        Save sv => {
                            stack.push(Frame.Restore { slot: sv.slot, old: slots[sv.slot] });
                            slots[sv.slot] = i;
                            pc = sv.next;
                        },
                        Match => { return; },
                    }
                }
            },
        }
    }
}

// The capture slots of the match [start, end): from the groups' places
// where every group has a fixed one, and by backtracking where not.
fn captures(re: Regex&, text: u8[:], start: i64, end: i64, slots: i64[:], visited: bool[>..]&) {
    guard re.placed else { backtrack(re, text, start, end, slots, visited); return; }
    for &p, k in re.places {
        slots[2 * k] = if p.start_back { end - p.start } else { start + p.start };
        slots[2 * k + 1] = if p.end_back { end - p.end } else { start + p.end };
    }
}

// F(captures) for every match each_match finds, as the crate's
// captures_iter yields them. The slots are reused from match to match.
fn each_captures<F>(re: Regex&, text: u8[:]) {
    var slots: i64[>..] = [];
    slots.resize(2 * re.groups, -1);
    var visited: bool[>..] = [];
    each_match(re, text) { s, e =>
        captures(re, text, s, e, slots, visited);
        F(Captures { text: text, slots: slots });
    };
}

// Appends text to out with every match replaced by F(captures), as the
// crate's replace_all with a closure: the text between matches stays as it
// is.
fn format_replaced<F>(out: u8[>..]&, re: Regex&, text: u8[:]) {
    var last = 0;
    each_captures(re, text) { caps =>
        out.append(text[last..caps.slots[0]]);
        out.append(F(caps));
        last = caps.slots[1];
    };
    out.append(text[last..]);
}

/stdlib/std.goose:
// The Goose standard library: `std` (docs/stdlib.md; the design is
// docs/design/stdlib_design.md).
// Functions over the language's own types; nothing here allocates, and
// nothing non-fixed is ever taken by value (spec §4.1). Fresh arrays come
// back as T[>..] and land in the caller's destination (§7.3); "maybe an
// element" is a T? into the input; positions are i64 with -1 for none.

// ---- scalars and bits --------------------------------------------------

fn min<T>(a: T, b: T) -> T { if b < a { return b; } return a; }
fn max<T>(a: T, b: T) -> T { if a < b { return b; } return a; }
fn clamp<T>(x: T, lo: T, hi: T) -> T {
    if x < lo { return lo; }
    if hi < x { return hi; }
    return x;
}

fn abs<T>(x: T) -> T { if x < 0 { return -x; } return x; }
fn abs(x: f32) -> f32 { if x < 0.0 { return -x; } return x; }
fn abs(x: f64) -> f64 { if x < 0.0 { return -x; } return x; }

fn sign<T>(x: T) -> T {
    if x < 0 { return -1; }
    if 0 < x { return 1; }
    return 0;
}
fn sign(x: f32) -> f32 {
    if x < 0.0 { return -1.0; }
    if 0.0 < x { return 1.0; }
    return 0.0;
}
fn sign(x: f64) -> f64 {
    if x < 0.0 { return -1.0; }
    if 0.0 < x { return 1.0; }
    return 0.0;
}

fn lerp(a: f32, b: f32, t: f32) -> f32 { a + (b - a) * t }
fn lerp(a: f64, b: f64, t: f64) -> f64 { a + (b - a) * t }

// The smallest power of two that is at least max(x, 1).
fn next_pow2(x: i64) -> i64 {
    var p = 1;
    while p < x { p = p * 2; }
    return p;
}

// The bits set, and the leading / trailing zero bits, 64 for zero: the
// runtime's (src/runtime/runtime_ext.h), one instruction where it can.
extern "gs_popcount" fn popcount(x: u64) -> i64;
extern "gs_clz" fn clz(x: u64) -> i64;
extern "gs_ctz" fn ctz(x: u64) -> i64;

// The values a and b refer to. `T&` of a reference type is that reference
// (spec §3.8), so for two elements of an array of references this swaps
// what they point to; swap_at swaps the elements themselves.
fn swap<T>(a: T&, b: T&) {
    let t = a;
    a = b;
    b = t;
}

// ---- hashing -------------------------------------------------------------
// One overload per scalar type: a u8 widens equally well into i64 and u64,
// so a single generic would be ambiguous. Integers get a multiply-xorshift
// mix (the low bits are what `dictionary` masks and keeps as slot tags). A
// negative integer mixes as its two's-complement bits, and a float as its
// count of 1/65536ths, truncated and wrapped to 64 bits: `as!`, since those
// conversions change the value on purpose.

fn hash_mix(x: u64) -> u64 {
    var h = x * 11400714819323198485;
    h = h ^ (h >> 32);
    return h;
}

fn hash(x: i8) -> u64 { hash_mix(x as! u64) }
fn hash(x: i16) -> u64 { hash_mix(x as! u64) }
fn hash(x: i32) -> u64 { hash_mix(x as! u64) }
fn hash(x: i64) -> u64 { hash_mix(x as! u64) }
fn hash(x: u8) -> u64 { hash_mix(x) }
fn hash(x: u16) -> u64 { hash_mix(x) }
fn hash(x: u32) -> u64 { hash_mix(x) }
fn hash(x: u64) -> u64 { hash_mix(x) }
fn hash(x: bool) -> u64 { if x { return hash_mix(1); } return hash_mix(2); }
fn hash(x: f32) -> u64 { hash_mix((x * 65536.0) as! u64) }
fn hash(x: f64) -> u64 { hash_mix((x * 65536.0) as! u64) }

// The 8 bytes of s from i, and the 4 bytes, little-endian; C compilers turn
// each into one load.
fn hash_le64(s: u8[:], i: i64) -> u64 {
    let c = s[i..i + 8];
    c[0] | (c[1] as u64) << 8 | (c[2] as u64) << 16 | (c[3] as u64) << 24 |
        (c[4] as u64) << 32 | (c[5] as u64) << 40 | (c[6] as u64) << 48 | (c[7] as u64) << 56
}
fn hash_le32(s: u8[:], i: i64) -> u64 {
    let c = s[i..i + 4];
    c[0] | (c[1] as u64) << 8 | (c[2] as u64) << 16 | (c[3] as u64) << 24
}

// Bytes, 8 at a time: one multiply and a rotate per word but the last,
// which is the final 8 bytes (overlapping the words before) or, for a short
// s, its bytes gathered into one word, and the length is the seed. The last
// word goes through two multiply-xorshift rounds, after which every input bit
// reaches the low bits. Keys longer than 24 bytes take hash_lanes, a call of
// its own from this early return, so that the short keys' code stays small
// enough for the C compiler to inline into a dictionary's lookups.
fn hash(s: u8[:]) -> u64 {
    let n = s.len;
    if n > 24 { return hash_lanes(s); }
    var h = (n as! u64) * 11400714819323198485;
    var w: u64 = 0;
    if n > 8 {
        var i = 0;
        while i < n - 8 {
            h = (h ^ hash_le64(s, i)) * 11400714819323198485;
            h = (h << 29) | (h >> 35);
            i += 8;
        }
        w = hash_le64(s, n - 8);
    } else if n >= 4 {
        w = hash_le32(s, 0) | hash_le32(s, n - 4) << 32;
    } else if n > 0 {
        w = s[0] | (s[n >> 1] as u64) << 8 | (s[n - 1] as u64) << 16;
    }
    h = (h ^ w) * 11400714819323198485;
    h = (h ^ (h >> 32)) * 15485907386658061715;
    return h ^ (h >> 32);
}

// hash of an s longer than 24 bytes. Each word's round waits for the one
// before, so the words before the last 24 bytes or fewer go to two lanes of
// rounds, the even and the odd words of each 16 bytes, which a processor
// overlaps; the second is folded into the first for the remaining words.
fn hash_lanes(s: u8[:]) -> u64 {
    let n = s.len;
    var h = (n as! u64) * 11400714819323198485;
    var g = h ^ 0x9E3779B97F4A7C15;
    var i = 0;
    while i < n - 24 {
        h = (h ^ hash_le64(s, i)) * 11400714819323198485;
        h = (h << 29) | (h >> 35);
        g = (g ^ hash_le64(s, i + 8)) * 11400714819323198485;
        g = (g << 29) | (g >> 35);
        i += 16;
    }
    h = h ^ ((g << 31) | (g >> 33));
    while i < n - 8 {
        h = (h ^ hash_le64(s, i)) * 11400714819323198485;
        h = (h << 29) | (h >> 35);
        i += 8;
    }
    h = (h ^ hash_le64(s, n - 8)) * 11400714819323198485;
    h = (h ^ (h >> 32)) * 15485907386658061715;
    return h ^ (h >> 32);
}

fn hash_combine(seed: u64, h: u64) -> u64 {
    seed ^ (h + 11400714819323198485 + (seed << 6) + (seed >> 2))
}

// ---- random numbers ---------------------------------------------------------
// splitmix64: one word of state, which is also the seed.

struct rng { s: u64 }

fn rand_u64(r: rng&) -> u64 {
    r.s = r.s + 11400714819323198485;
    var z = r.s;
    z = (z ^ (z >> 30)) * 13787848793156543929;
    z = (z ^ (z >> 27)) * 10723151780598845931;
    return z ^ (z >> 31);
}

// Uniform in [0, n).
fn rand_int(r: rng&, n: i64) -> i64 { (rand_u64(r) % (n as u64)) as i64 }

// Uniform in [0, 1).
fn rand_flt(r: rng&) -> f64 { (rand_u64(r) >> 11) * (1.0 / 9007199254740992.0) }

// Fisher-Yates.
// The functions that move elements around store whole elements with `.=`,
// which moves a reference element itself rather than writing through it
// (spec §3.8), and hold one in a `T` local, which keeps a reference: the
// plain one, for relative elements, which the store back encodes (§3.9).
fn shuffle<T>(xs: T[:], r: rng&) {
    var i = xs.len - 1;
    while i > 0 {
        let j = rand_int(r, i + 1);
        let t: T = xs[i];
        xs[i] .= xs[j];
        xs[j] .= t;
        i -= 1;
    }
}

// ---- arrays: reading and searching -------------------------------------------

fn swap_at<T>(xs: T[:], i: i64, j: i64) {
    let t: T = xs[i];
    xs[i] .= xs[j];
    xs[j] .= t;
}

// F(x), last to first.
fn each_rev<T, F>(xs: T[:]) {
    var i = xs.len;
    while i > 0 {
        i -= 1;
        F(xs[i]);
    }
}

// F(chunk, i) over consecutive slices of n elements; the last may be short.
fn each_chunk<T, F>(xs: T[:], n: i64) {
    var i = 0;
    var k = 0;
    while i < xs.len {
        let e = min(i + n, xs.len);
        F(xs[i..e], k);
        i = e;
        k += 1;
    }
}

// The first x with F(x), as a reference into xs; null if none.
fn find<T, F>(xs: T[:]) -> T? {
    for &x in xs { if F(x) { return x; } }
    return null;
}

fn find_index<T, F>(xs: T[:]) -> i64 {
    for x, i in xs { if F(x) { return i; } }
    return -1;
}

// The first i with xs[i] == v, -1 if none. (`index_of` is the builtin that
// turns an element reference into its index.)
fn position<T>(xs: T[:], v: T) -> i64 {
    for x, i in xs { if x == v { return i; } }
    return -1;
}

fn contains<T>(xs: T[:], v: T) -> bool { position(xs, v) >= 0 }

fn any<T, F>(xs: T[:]) -> bool {
    for x in xs { if F(x) { return true; } }
    return false;
}

fn all<T, F>(xs: T[:]) -> bool {
    for x in xs { if !F(x) { return false; } }
    return true;
}

fn count<T, F>(xs: T[:]) -> i64 {
    var n = 0;
    for x in xs { if F(x) { n += 1; } }
    return n;
}

fn min<T>(xs: T[:]) -> T {
    assert(xs.len > 0);
    var m = xs[0];
    for x in xs { if x < m { m = x; } }
    return m;
}
fn min<T, F>(xs: T[:]) -> T {
    assert(xs.len > 0);
    var m = xs[0];
    for x in xs { if F(x, m) { m = x; } }
    return m;
}
fn max<T>(xs: T[:]) -> T {
    assert(xs.len > 0);
    var m = xs[0];
    for x in xs { if m < x { m = x; } }
    return m;
}
fn max<T, F>(xs: T[:]) -> T {
    assert(xs.len > 0);
    var m = xs[0];
    for x in xs { if F(m, x) { m = x; } }
    return m;
}

// The index of the element with the smallest / largest key F(x); -1 if empty.
fn min_by<T, F>(xs: T[:]) -> i64 {
    if xs.len == 0 { return -1; }
    var best = 0;
    var bk = F(xs[0]);
    for x, i in xs {
        let k = F(x);
        if k < bk { bk = k; best = i; }
    }
    return best;
}
fn max_by<T, F>(xs: T[:]) -> i64 {
    if xs.len == 0 { return -1; }
    var best = 0;
    var bk = F(xs[0]);
    for x, i in xs {
        let k = F(x);
        if bk < k { bk = k; best = i; }
    }
    return best;
}

fn last<T>(xs: T[:]) -> T& {
    assert(xs.len > 0);
    xs[xs.len - 1]
}

// The first i with !F(xs[i]), where F holds on a prefix of xs.
fn lower_bound<T, F>(xs: T[:]) -> i64 {
    var lo = 0;
    var hi = xs.len;
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if F(xs[mid]) { lo = mid + 1; } else { hi = mid; }
    }
    return lo;
}

// xs sorted by <: the position of v (or where it would go), and whether it is there.
fn binary_search<T>(xs: T[:], v: T) -> i64, bool {
    var lo = 0;
    var hi = xs.len;
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if xs[mid] < v { lo = mid + 1; } else { hi = mid; }
    }
    return lo, lo < xs.len && xs[lo] == v;
}

// The first / last occurrence of a subsequence, -1 if none.
fn find<T>(xs: T[:], sub: T[:]) -> i64 {
    if sub.len == 0 { return 0; }
    var i = 0;
    while i + sub.len <= xs.len {
        if xs[i] == sub[0] && xs[i..i + sub.len] == sub { return i; }
        i += 1;
    }
    return -1;
}
fn rfind<T>(xs: T[:], sub: T[:]) -> i64 {
    if sub.len == 0 { return xs.len; }
    if sub.len > xs.len { return -1; }
    var i = xs.len - sub.len;
    while i >= 0 {
        if xs[i] == sub[0] && xs[i..i + sub.len] == sub { return i; }
        i -= 1;
    }
    return -1;
}

fn starts_with<T>(xs: T[:], p: T[:]) -> bool { p.len <= xs.len && xs[..p.len] == p }
fn ends_with<T>(xs: T[:], p: T[:]) -> bool { p.len <= xs.len && xs[xs.len - p.len..] == p }

// ---- byte sets ------------------------------------------------------------------

// A set of bytes, prepared by byte_set for find_any and find_pair, which the
// runtime runs over 16 bytes at a time where it can (gs_scan_any in
// src/runtime/runtime_impl.h, whose gs_byteset has this layout). `members`
// is the set. The rest says how a block is tested for it: kind 1 to 3 by
// comparing with that many of `bytes`, kind 4 as the range bytes[0] ..
// bytes[0] + bytes[1], kind 0 being the empty set, and with `invert` the set
// is the complement of what the kind describes. Every set also has tables,
// bit k of lo[j] standing for the byte k * 16 + j and of hi[j] for 128 + k *
// 16 + j, which are all a set of kind 5 is tested by.
struct ByteSet {
    members: bool[256],
    kind: u8,
    invert: bool,
    bytes: u8[3],
    lo: u8[16],
    hi: u8[16],
}

fn byte_set(members: bool[256]) -> ByteSet {
    var n = 0;
    for m in members { if m { n += 1; } }
    var s = ByteSet { members: members, kind: 5, invert: false, bytes: [0; 3], lo: [0; 16],
                      hi: [0; 16] };
    for b in 256 {
        if members[b] {
            let bit = (1 << ((b >> 4) & 7)) as u8;
            if b < 128 { s.lo[b & 15] |= bit; } else { s.hi[b & 15] |= bit; }
        }
    }
    // The bytes a kind describes: the members, or the others where those
    // are fewer.
    let invert = n > 128;
    var k = 0;
    var first = 0;
    var last = 0;
    for b in 256 {
        if members[b] != invert {
            if k == 0 { first = b; }
            if k < 3 { s.bytes[k] = b as u8; }
            last = b;
            k += 1;
        }
    }
    if k <= 3 {
        s.kind = k as u8;
        s.invert = invert;
        for j in k..3 { s.bytes[j] = s.bytes[0]; }
    } else if last - first + 1 == k {
        s.kind = 4;
        s.invert = invert;
        s.bytes[0] = first as u8;
        s.bytes[1] = (last - first) as u8;
    }
    return s;
}

// The set of the bytes in `bytes`.
fn byte_set(bytes: u8[:]) -> ByteSet {
    var members: bool[256] = [false; 256];
    for b in bytes { members[b] = true; }
    return byte_set(members);
}

// The first i with s[i] in the set, -1 if none.
extern "gs_find_any" fn find_any(s: const u8[:], set: const ByteSet&) -> i64;

// find_pair, but for its check of d.
extern "gs_find_pair" fn byte_set_pair(s: const u8[:], a: const ByteSet&, d: i64,
                                       b: const ByteSet&) -> i64;

// The first i with s[i] in a and s[i + d] in b, of those with i + d < s.len;
// -1 if none. d >= 0.
fn find_pair(s: u8[:], a: const ByteSet&, d: i64, b: const ByteSet&) -> i64 {
    assert(d >= 0);
    return byte_set_pair(s, a, d, b);
}

// ---- arrays: transforming ------------------------------------------------------

fn map<T, F>(xs: T[:]) {
    var out = [];
    for x in xs { out.push(F(x)); }
    return out;
}

fn filter<T, F>(xs: T[:]) -> T[>..] {
    var out: T[>..] = [];
    for x in xs { if F(x) { out.push(copy(x)); } }
    return out;
}

// acc = F(acc, x) for each x, from the seed.
fn fold<T, A, F>(xs: T[:], acc: A) -> A {
    var a = acc;
    for x in xs { a = F(a, x); }
    return a;
}

fn sum<T>(xs: T[:]) -> T {
    var s = default<T>();
    for x in xs { s += x; }
    return s;
}

fn concat<T>(a: T[:], b: T[:]) -> T[>..] {
    var out: T[>..] = [];
    out.append(a);
    out.append(b);
    return out;
}

// ---- arrays: in place -------------------------------------------------------------

fn fill<T>(xs: T[:], v: T) { for i in xs.len { xs[i] .= v; } }

// Element by element, first to last; the lengths must agree.
fn copy_into<T>(dst: T[:], src: T[:]) {
    assert(dst.len == src.len);
    for i in dst.len { dst[i] .= src[i]; }
}

fn reverse<T>(xs: T[:]) {
    var i = 0;
    var j = xs.len - 1;
    while i < j {
        swap_at(xs, i, j);
        i += 1;
        j -= 1;
    }
}

// ASCII, in place.
fn to_lower(s: u8[:]) { for &c in s { if c >= 'A' && c <= 'Z' { c += 32; } } }
fn to_upper(s: u8[:]) { for &c in s { if c >= 'a' && c <= 'z' { c -= 32; } } }

// ---- arrays: sorting -----------------------------------------------------------
// The sort_ helpers take the comparator as F, "a goes before b", and are
// only meant to be called from sort and stable_sort. Every index they use
// stays in range whatever F returns, so a comparator that is no strict weak
// ordering leaves some permutation of the input rather than an abort.

// Insertion sort. Stable: an element moves only past those it goes strictly
// before.
fn sort_insertion<T, F>(v: T[:]) {
    for i in 1..v.len {
        let x: T = v[i];
        var j = i;
        while j > 0 {
            let y: T = v[j - 1];
            if !F(x, y) { break; }
            v[j] .= y;
            j -= 1;
        }
        v[j] .= x;
    }
}

// The length of the run v starts with: elements in order, or in strictly
// descending order, which are reversed in place so that they are in order
// too. Reversing a strictly descending run keeps a stable sort stable.
fn sort_run<T, F>(v: T[:]) -> i64 {
    if v.len < 2 { return v.len; }
    var e = 2;
    if F(v[1], v[0]) {
        while e < v.len {
            if !F(v[e], v[e - 1]) { break; }
            e += 1;
        }
        reverse(v[..e]);
    } else {
        while e < v.len {
            if F(v[e], v[e - 1]) { break; }
            e += 1;
        }
    }
    return e;
}

// The index of the median of v[a], v[b] and v[c].
fn sort_median3<T, F>(v: T[:], a: i64, b: i64, c: i64) -> i64 {
    let x = F(v[a], v[b]);
    if x != F(v[a], v[c]) { return a; }
    // v[a] goes before both others (x) or after both: the median is the
    // first of the other two, or the last.
    if F(v[b], v[c]) != x { return c; }
    return b;
}

// A pivot for v, at least 8 long: the median of elements at 0, 4/8 and 7/8
// of the way, and from 128 elements on the median of three such medians,
// each over its own eighth of v.
fn sort_pivot<T, F>(v: T[:]) -> i64 {
    let n8 = v.len / 8;
    let a = 0;
    let b = n8 * 4;
    let c = n8 * 7;
    if v.len < 128 { return sort_median3(v, a, b, c) { x, y => F(x, y) }; }
    let m8 = n8 / 8;
    let ma = sort_median3(v, a, a + m8 * 4, a + m8 * 7) { x, y => F(x, y) };
    let mb = sort_median3(v, b, b + m8 * 4, b + m8 * 7) { x, y => F(x, y) };
    let mc = sort_median3(v, c, c + m8 * 4, c + m8 * 7) { x, y => F(x, y) };
    return sort_median3(v, ma, mb, mc) { x, y => F(x, y) };
}

// Moves the elements x of v[1..] with F(x, v[0]) to the front of v[1..] and
// returns how many there are; v[0] is the pivot and stays. Every step swaps
// and advances the boundary by the comparison's outcome, so the loop has no
// branch on the data (a branchless Lomuto partition).
fn sort_partition<T, F>(v: T[:]) -> i64 {
    let p: T = v[0];
    var lt = 1;
    for i in 1..v.len {
        let x: T = v[i];
        v[i] .= v[lt];
        v[lt] .= x;
        lt += if F(x, p) { 1 } else { 0 };
    }
    return lt - 1;
}

// Heapsort: O(n log n) whatever the input, for ranges partitioning keeps
// splitting badly.
fn sort_heap<T, F>(v: T[:]) {
    var i = v.len / 2;
    while i > 0 {
        i -= 1;
        sift_down(v, i) { a, b => F(b, a) };
    }
    var end = v.len;
    while end > 1 {
        end -= 1;
        swap_at(v, 0, end);
        sift_down(v[..end], 0) { a, b => F(b, a) };
    }
}

// Unstable, in place, no allocation: a pattern-defeating quicksort after
// pdqsort and Rust's ipnsort. Input already in order, or in strictly
// descending order, takes one pass. Otherwise each round partitions a range
// around a median pivot without branching on the comparisons, defers the
// larger side on a stack of ranges (at most log2(n) of them) and goes on
// with the smaller one. Everything left of a range goes before or with
// everything in it, so a range whose pivot does not go after the element
// just before the range has nothing that goes before the pivot: one
// partition moves the elements equal to the pivot to the front, where they
// are done, and many equal keys cost linear passes rather than n log n. A
// range still being partitioned 2 log2(n) rounds deep is heapsorted, which
// bounds the worst case at O(n log n). Ranges of 10 or fewer are insertion
// sorted: its mispredicted loop exits make it slower than partitioning
// above that.
fn sort<T>(xs: T[:]) { sort(xs) { a, b => a < b } }
fn sort<T, F>(xs: T[:]) {
    let n = xs.len;
    if n <= 10 {
        sort_insertion(xs) { a, b => F(a, b) };
        return;
    }
    let r = sort_run(xs) { a, b => F(a, b) };
    if r == n { return; }
    var limit = 2 * (63 - clz(n as u64));
    var st: i64[..144] = [];   // lo, hi, limit per deferred range
    var lo = 0;
    var hi = n;
    loop {
        let v = xs[lo..hi];
        if v.len > 10 && limit > 0 {
            limit -= 1;
            swap_at(v, 0, sort_pivot(v) { a, b => F(a, b) });
            if lo > 0 && !F(xs[lo - 1], v[0]) {
                let m = sort_partition(v) { a, b => !F(b, a) };
                swap_at(v, 0, m);
                lo += m + 1;
                continue;
            }
            let m = sort_partition(v) { a, b => F(a, b) };
            swap_at(v, 0, m);
            if m < v.len - 1 - m {
                st.push(lo + m + 1);
                st.push(hi);
                st.push(limit);
                hi = lo + m;
            } else {
                st.push(lo);
                st.push(lo + m);
                st.push(limit);
                lo += m + 1;
            }
            continue;
        }
        if v.len > 10 {
            sort_heap(v) { a, b => F(a, b) };
        } else {
            sort_insertion(v) { a, b => F(a, b) };
        }
        if st.len == 0 { return; }
        limit = st.pop();
        hi = st.pop();
        lo = st.pop();
    }
}

// Merges the sorted runs l and r into d, as long as both; on ties l's
// element comes first. Runs already in order are copied. Where the output
// switches between the runs often, as on random input, a branch on each
// comparison mispredicts about every other step, so the step selects its
// element and side with conditional moves instead. Where it rarely
// switches, a predicted branch runs ahead of the comparisons, which matters
// most for comparators that load what they compare. `chaotic` chooses the
// form, and the merge leaves its own verdict in it for the next one.
fn sort_merge<T, F>(l: T[:], r: T[:], d: T[:], chaotic: bool&) {
    if !F(r[0], l[l.len - 1]) {
        copy_into(d[..l.len], l);
        copy_into(d[l.len..], r);
        return;
    }
    var a = 0;
    var b = 0;
    var k = 0;
    var switches = 0;
    var last_r = false;
    if chaotic {
        while a < l.len && b < r.len {
            let take_r = F(r[b], l[a]);
            d[k] .= if take_r { r[b] } else { l[a] };
            if take_r { b += 1; } else { a += 1; }
            if take_r != last_r { switches += 1; }
            last_r = take_r;
            k += 1;
        }
    } else {
        while a < l.len && b < r.len {
            if F(r[b], l[a]) {
                d[k] .= r[b];
                b += 1;
                if !last_r { switches += 1; }
                last_r = true;
            } else {
                d[k] .= l[a];
                a += 1;
                if last_r { switches += 1; }
                last_r = false;
            }
            k += 1;
        }
    }
    chaotic = switches * 4 > k;
    if a < l.len {
        copy_into(d[k..], l[a..]);
    } else {
        copy_into(d[k..], r[b..]);
    }
}

// Stable: a natural merge sort. One pass finds the runs, elements in order
// or in strictly descending order (reversed), extending each run shorter
// than 16 by insertion sort; then passes merge neighboring runs in pairs,
// alternating between xs and one temporary of xs.len elements on a fresh
// stack, so that no pass copies back. The first pass merges out of the
// temporary where the number of passes is odd, so that the last one lands
// in xs. Input that is one run takes the first pass alone, and 20 or fewer
// elements are insertion sorted; neither allocates.
fn stable_sort<T>(xs: T[:]) { stable_sort(xs) { a, b => a < b } }
fn stable_sort<T, F>(xs: T[:]) {
    let n = xs.len;
    if n <= 20 {
        sort_insertion(xs) { a, b => F(a, b) };
        return;
    }
    var r = sort_run(xs) { a, b => F(a, b) };
    if r == n { return; }
    // The end of every run, in order.
    var ends: i64[>..] = [];
    var lo = 0;
    loop {
        let v = xs[lo..];
        if r < 16 && r < v.len {
            r = min(16, v.len);
            sort_insertion(v[..r]) { a, b => F(a, b) };
        }
        lo += r;
        ends.push(lo);
        if lo >= n { break; }
        r = sort_run(xs[lo..]) { a, b => F(a, b) };
    }
    var tmp: T[>..] = [];
    tmp.append(xs);
    var passes = 0;
    var runs = ends.len;
    while runs > 1 {
        runs = (runs + 1) / 2;
        passes += 1;
    }
    var into_tmp = passes % 2 == 0;
    var chaotic = true;
    while ends.len > 1 {
        let src: T[:] = if into_tmp { xs } else { tmp };
        let dst: T[:] = if into_tmp { tmp } else { xs };
        var start = 0;
        var w = 0;
        var i = 0;
        while i < ends.len {
            let mid = ends[i];
            var end = mid;
            if i + 1 < ends.len {
                end = ends[i + 1];
                sort_merge(src[start..mid], src[mid..end], dst[start..end], chaotic) { a, b => F(a, b) };
            } else {
                copy_into(dst[start..end], src[start..end]);
            }
            ends[w] = end;
            w += 1;
            start = end;
            i += 2;
        }
        ends.resize(w);
        into_tmp = !into_tmp;
    }
}

// ---- arrays: changing the length -------------------------------------------------
// `xs: A&` binds the whole array, so each instantiates only for array kinds
// that have the operations it uses.

fn push_n<A, T>(xs: A&, v: T, n: i64) { for i in n { xs.push(v); } }

fn insert_at<A, T>(xs: A&, i: i64, v: T) {
    xs.push(v);
    var j = xs.len - 1;
    while j > i {
        xs[j] .= xs[j - 1];
        j -= 1;
    }
    xs[i] .= v;
}

// Removes and returns xs[i], shifting the rest down. The result is a copy
// of the value, as `let v = xs[i]` makes one (of the pointee, for a
// reference element), here and in swap_remove and heap_pop.
fn remove_at<A>(xs: A&, i: i64) {
    let v = xs[i];
    var j = i;
    while j + 1 < xs.len {
        xs[j] .= xs[j + 1];
        j += 1;
    }
    xs.pop();
    return v;
}

// Removes and returns xs[i] in O(1), moving the last element into its place.
fn swap_remove<A>(xs: A&, i: i64) {
    let v = xs[i];
    xs[i] .= xs[xs.len - 1];
    xs.pop();
    return v;
}

// Keeps the elements with F(x), in order.
fn retain<A, F>(xs: A&) {
    var w = 0;
    for i in xs.len {
        if F(xs[i]) {
            xs[w] .= xs[i];
            w += 1;
        }
    }
    xs.resize(w);
}

// Drops adjacent duplicates (sort first to drop all).
fn dedup<A>(xs: A&) {
    if xs.len == 0 { return; }
    var w = 1;
    var i = 1;
    while i < xs.len {
        if !(xs[i] == xs[w - 1]) {
            xs[w] .= xs[i];
            w += 1;
        }
        i += 1;
    }
    xs.resize(w);
}

// A binary min-heap by < (or by F(a, b), "a goes before b"). The sifts move
// a hole rather than swapping: the element being placed waits in a local,
// each level moves one element into the hole, and the element is stored once
// where the hole stops. For a comparator that is a strict weak order, every
// operation leaves the layout that swapping the element along would.
fn heap_push<A, T>(xs: A&, v: T) { heap_push(xs, v) { a, b => a < b } }
fn heap_push<A, T, F>(xs: A&, v: T) {
    xs.push(v);
    sift_up(xs, xs.len - 1) { a, b => F(a, b) };
}

// Moves xs[start] towards the root past every element it goes before. The
// element is read back from the array rather than taken from heap_push's v,
// whose type may differ from the elements' (an i32 pushed into i64s), and
// held in a T, the element type, which keeps a reference element itself.
fn sift_up<T, F>(xs: T[:], start: i64) {
    var i = start;
    let x: T = xs[i];
    while i > 0 {
        let p = (i - 1) / 2;
        if !F(x, xs[p]) { break; }
        xs[i] .= xs[p];
        i = p;
    }
    xs[i] .= x;
}

fn sift_down<T, F>(xs: T[:], start: i64) {
    let n = xs.len;
    var i = start;
    if 2 * i + 1 >= n { return; }   // A leaf, or a start past the end, is not read.
    let x: T = xs[i];
    loop {
        let l = 2 * i + 1;
        if l >= n { break; }
        var m = l;
        let r = l + 1;
        if r < n && F(xs[r], xs[l]) { m = r; }
        if !F(xs[m], x) { break; }
        xs[i] .= xs[m];
        i = m;
    }
    xs[i] .= x;
}

// The hole left at the root walks down to a leaf along the child that goes
// first, and the last element then sifts up from there, as in libstdc++ and
// Rust: the last element nearly always belongs near the bottom, so this
// takes about one comparison per level where sifting it down takes two.
fn heap_pop<A>(xs: A&) { heap_pop(xs) { a, b => a < b } }
fn heap_pop<A, F>(xs: A&) {
    let top = xs[0];
    sift_hole(xs) { a, b => F(a, b) };
    // Popped after the sift: for an array of references the checker rejects
    // a pop that a use of the array follows (implementation.md §10).
    xs.pop();
    return top;
}

// Fills the hole heap_pop leaves at the root of xs[..n] with x = xs[n], the
// element it pops off the end afterwards; x is held in a T, the element
// type, which keeps a reference element itself.
fn sift_hole<T, F>(xs: T[:]) {
    let n = xs.len - 1;
    if n == 0 { return; }
    let x: T = xs[n];
    var i = 0;
    var c = 1;
    while c < n - 1 {
        if F(xs[c + 1], xs[c]) { c += 1; }
        xs[i] .= xs[c];
        i = c;
        c = 2 * c + 1;
    }
    if c == n - 1 {
        xs[i] .= xs[c];
        i = c;
    }
    // Going up, x passes every element that does not go before it, ties
    // included, and stops below the first that does: where sifting it down
    // from the root would have stopped.
    while i > 0 {
        let p = (i - 1) / 2;
        if F(xs[p], x) { break; }
        xs[i] .= xs[p];
        i = p;
    }
    xs[i] .= x;
}

fn make_heap<A>(xs: A&) { make_heap(xs) { a, b => a < b } }
fn make_heap<A, F>(xs: A&) {
    var i = xs.len / 2;
    while i > 0 {
        i -= 1;
        sift_down(xs, i) { a, b => F(a, b) };
    }
}

// ---- strings ---------------------------------------------------------------------
// Plain rendering is the builtin `format`; these add control and parsing.

// Digits of v in the base (2..36), right-aligned in `width` with `pad`,
// appended to `out`, any u8 array that grows (u8[>..], or a limited u8[..k]).
// Base ten is the builtin text of the integer, the runtime's digit loop
// writing straight into `out`; other bases divide by the `base` parameter,
// a real division per digit.
fn format_uint<B>(out: B&, v: u64, base: i64, width: i64, padc: u8) {
    if base == 10 {
        if width > 1 {
            var n = 1;
            var x = v;
            while x >= 10 {
                x /= 10;
                n += 1;
            }
            var padn = width - n;
            while padn > 0 {
                out.push(padc);
                padn -= 1;
            }
        }
        format(out, v);
        return;
    }
    var digits: u8[..64] = [];
    var x = v;
    if x == 0 { digits.push('0'); }
    let b = base as u64;
    while x > 0 {
        let d = (x % b) as i64;
        var c: u8 = 0;
        if d < 10 { c = ('0' + d) as u8; } else { c = ('a' + d - 10) as u8; }
        digits.push(c);
        x = x / b;
    }
    var padn = width - digits.len;
    while padn > 0 {
        out.push(padc);
        padn -= 1;
    }
    each_rev(digits) { out.push(it); };
}

// The sign goes in front of any padding: -0042. The magnitude is taken in
// unsigned arithmetic, which holds i64.min's.
fn format_int<B>(out: B&, v: i64, base: i64, width: i64, padc: u8) {
    if v < 0 {
        out.push('-');
        format_uint(out, 0 - v as! u64, base, width - 1, padc);
    } else {
        format_uint(out, v as u64, base, width, padc);
    }
}

// ULEB128 (§3.6), the encoding an image's framing prefix uses
// (docs/design/serialization.md): what to_bytes writes in front of an
// array's bytes, so that a reader of a stream or a file can size its read
// before it has the whole image.
fn format_uleb(out: u8[>..]&, v: i64) {
    var x = v as u64;
    loop {
        let b = (x & 0x7f) as u8;
        x >>= 7;
        if x == 0 { out.push(b); return; }
        out.push(b | 0x80);
    }
}

// The ULEB128 at the front of s: its value and its byte count, or 0, 0 when
// the bytes do not hold one (unterminated, or past the 64-bit range).
fn parse_uleb(s: u8[:]) -> i64, i64 {
    var v = 0 as u64;
    var shift = 0;
    var i = 0;
    while i < s.len && i < 10 {
        let b = s[i];
        if shift > 63 || (shift == 63 && (b & 0x7e) != 0) { return 0, 0; }
        v |= (b & 0x7f) as u64 << shift;
        i++;
        if b < 0x80 { return v as i64, i; }
        shift += 7;
    }
    return 0, 0;
}

// v with a fixed number of decimals, rounded half up; infinities and NaN
// in their text form (§3.7).
fn format_flt(out: u8[>..]&, v: f64, decimals: i64) {
    if v != v || v - v != 0.0 {
        format(out, v);
        return;
    }
    var x = v;
    if x < 0.0 {
        out.push('-');
        x = -x;
    }
    var scale = 1.0;
    for i in decimals { scale *= 10.0; }
    // x is not negative, so truncation is floor and adding 0.5 first rounds
    // half up: `as!`, since dropping the fraction is the point.
    let scaled = (x * scale + 0.5) as! i64;
    let iscale = scale as i64;
    format_uint(out, (scaled / iscale) as u64, 10, 0, ' ');
    if decimals > 0 {
        out.push('.');
        format_uint(out, (scaled % iscale) as u64, 10, decimals, '0');
    }
}

// An optionally signed whole-string integer; false on anything else, including a value outside i64.
fn parse_int(s: u8[:], base: i64 = 10) -> i64, bool {
    var i = 0;
    var neg = false;
    if s.len > 0 && (s[0] == '-' || s[0] == '+') {
        neg = s[0] == '-';
        i = 1;
    }
    if i >= s.len { return 0, false; }
    // The magnitude accumulates as a negative number: -2^63 has no positive
    // counterpart, while every other magnitude has a negative one. `d < base`
    // is checked first, so `base` is positive in the overflow test; dividing
    // truncates toward zero, which is the ceiling for these negative bounds.
    let min = -9223372036854775807 - 1;
    var v = 0;
    while i < s.len {
        let c = s[i] as i64;
        var d = -1;
        if c >= '0' && c <= '9' { d = c - '0'; }
        else if c >= 'a' && c <= 'z' { d = c - 'a' + 10; }
        else if c >= 'A' && c <= 'Z' { d = c - 'A' + 10; }
        if d < 0 || d >= base { return 0, false; }
        if v < (min + d) / base { return 0, false; }
        v = v * base - d;
        i += 1;
    }
    if !neg {
        if v == min { return 0, false; }
        v = -v;
    }
    return v, true;
}

// 10^0 .. 10^22: every one exact in binary64, which is what makes one
// multiply or divide by it correctly rounded. `const`, so it is static C
// data rather than a member of each program instance's globals.
const parse_flt_pow10: f64[23] = [1e0, 1e1, 1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8, 1e9, 1e10, 1e11,
                                  1e12, 1e13, 1e14, 1e15, 1e16, 1e17, 1e18, 1e19, 1e20, 1e21, 1e22];

// A decimal float with optional sign, fraction and exponent; false otherwise.
fn parse_flt(s: u8[:]) -> f64, bool {
    var i = 0;
    var neg = false;
    if s.len > 0 && (s[0] == '-' || s[0] == '+') {
        neg = s[0] == '-';
        i = 1;
    }
    // The significant digits as one integer, with the decimal exponent
    // adjusted for the digits after the point, so the value is
    // mant * 10^exp10. One test per digit (the u8 subtraction wraps below
    // '0'), and the digits are counted from positions.
    let start = i;
    var mant: u64 = 0;
    while i < s.len {
        let d = s[i] - '0';
        if d >= 10 { break; }
        mant = mant * 10 + d;
        i += 1;
    }
    var digits = i - start;
    var exp10 = 0;
    if i < s.len && s[i] == '.' {
        i += 1;
        let fstart = i;
        while i < s.len {
            let d = s[i] - '0';
            if d >= 10 { break; }
            mant = mant * 10 + d;
            i += 1;
        }
        exp10 = fstart - i;
        digits -= exp10;
    }
    if digits == 0 { return 0.0, false; }
    // Up to 19 digits fit a u64 exactly. With no exponent either, the value
    // is that integer over an exact power of ten, the scaling below in one
    // step. Up to 18 they fit an i64 too, which converts to f64 in one
    // instruction where a u64 takes several on x86-64, to the same value.
    if digits <= 19 && i == s.len {
        var v = 0.0;
        if digits <= 18 { v = mant as! i64; } else { v = mant; }
        if exp10 < 0 { v /= parse_flt_pow10[-exp10]; }
        if neg { v = -v; }
        return v, true;
    }
    if digits > 19 {
        // mant may have wrapped above: read the digits again keeping the
        // first 19 significant digits, with the exponent counting integer
        // digits dropped past them. Leading fractional zeroes only adjust
        // the exponent. These loops stop where those did, at i.
        mant = 0;
        exp10 = 0;
        var mdigits = 0;
        var j = start;
        while j < s.len && s[j] == '0' { j += 1; }
        while j < s.len && s[j] - '0' < 10 {
            if mdigits < 19 { mant = mant * 10 + (s[j] - '0'); mdigits += 1; }
            else { exp10 += 1; }
            j += 1;
        }
        if j < s.len && s[j] == '.' {
            j += 1;
            if mant == 0 {
                while j < s.len && s[j] == '0' { exp10 -= 1; j += 1; }
            }
            while j < s.len && s[j] - '0' < 10 {
                if mdigits < 19 { mant = mant * 10 + (s[j] - '0'); mdigits += 1; exp10 -= 1; }
                j += 1;
            }
        }
    }
    if i < s.len && (s[i] == 'e' || s[i] == 'E') {
        i += 1;
        var eneg = false;
        if i < s.len && (s[i] == '-' || s[i] == '+') {
            eneg = s[i] == '-';
            i += 1;
        }
        var e = 0;
        var edigits = 0;
        while i < s.len && s[i] >= '0' && s[i] <= '9' {
            if e < 100000 { e = e * 10 + (s[i] - '0'); }
            edigits += 1;
            i += 1;
        }
        if edigits == 0 { return 0.0, false; }
        exp10 += if eneg { -e } else { e };
    }
    // A mantissa below 2^53 converts exactly and a power of ten up to 10^22
    // is exact in binary64, so one multiply or divide is correctly rounded
    // (Clinger's fast path); longer inputs and larger exponents scale in
    // steps and may be off by an ulp. A longer mantissa rounds as it
    // converts.
    var v: f64 = mant;
    var e = exp10;
    while e > 22 { v *= 1e22; e -= 22; }
    while e < -22 { v /= 1e22; e += 22; }
    if e > 0 { v *= parse_flt_pow10[e]; } else if e < 0 { v /= parse_flt_pow10[-e]; }
    if i != s.len { return 0.0, false; }
    if neg { v = -v; }
    return v, true;
}

// Bytewise lexicographic: -1, 0, 1.
fn compare(a: u8[:], b: u8[:]) -> i64 {
    let n = min(a.len, b.len);
    for i in n {
        if a[i] < b[i] { return -1; }
        if b[i] < a[i] { return 1; }
    }
    if a.len < b.len { return -1; }
    if b.len < a.len { return 1; }
    return 0;
}

fn is_space(c: u8) -> bool { c == ' ' || c == '\t' || c == '\n' || c == '\r' }

// ASCII whitespace trimmed: a sub-slice of s, no copy.
fn trim_start(s: u8[:]) -> u8[:] {
    var i = 0;
    while i < s.len && is_space(s[i]) { i += 1; }
    return s[i..];
}
fn trim_end(s: u8[:]) -> u8[:] {
    var e = s.len;
    while e > 0 && is_space(s[e - 1]) { e -= 1; }
    return s[..e];
}
fn trim(s: u8[:]) -> u8[:] { trim_end(trim_start(s)) }

// The parts between separators, as slices into s; empty parts are kept. The
// parts are read-only views, so the same function serves a literal and a
// buffer alike (§9.5).
fn split(s: u8[:], sep: u8) -> const u8[:][>..] {
    var out: const u8[:][>..] = [];
    var start = 0;
    for c, i in s {
        if c == sep {
            out.push(s[start..i]);
            start = i + 1;
        }
    }
    out.push(s[start..]);
    return out;
}
// A separator of several bytes, matched from the left, so occurrences never
// overlap; an empty one leaves s whole.
fn split(s: u8[:], sep: u8[:]) -> const u8[:][>..] {
    var out: const u8[:][>..] = [];
    if sep.len == 0 {
        out.push(s);
        return out;
    }
    var start = 0;
    var i = 0;
    while i + sep.len <= s.len {
        if s[i..i + sep.len] == sep {
            out.push(s[start..i]);
            i += sep.len;
            start = i;
        } else {
            i += 1;
        }
    }
    out.push(s[start..]);
    return out;
}

// F(part) for each part, without building the array.
fn each_split<F>(s: u8[:], sep: u8) {
    var start = 0;
    for c, i in s {
        if c == sep {
            F(s[start..i]);
            start = i + 1;
        }
    }
    F(s[start..]);
}
fn each_split<F>(s: u8[:], sep: u8[:]) {
    if sep.len == 0 {
        F(s);
        return;
    }
    var start = 0;
    var i = 0;
    while i + sep.len <= s.len {
        if s[i..i + sep.len] == sep {
            F(s[start..i]);
            i += sep.len;
            start = i;
        } else {
            i += 1;
        }
    }
    F(s[start..]);
}

// The words of s, as slices into it: the runs of bytes between ASCII
// whitespace (is_space, as trim), so no word is empty.
fn words(s: u8[:]) -> const u8[:][>..] {
    var out: const u8[:][>..] = [];
    var i = 0;
    while i < s.len {
        while i < s.len && is_space(s[i]) { i += 1; }
        let start = i;
        while i < s.len && !is_space(s[i]) { i += 1; }
        if i > start { out.push(s[start..i]); }
    }
    return out;
}

// F(word) for each word, without building the array.
fn each_word<F>(s: u8[:]) {
    var i = 0;
    while i < s.len {
        while i < s.len && is_space(s[i]) { i += 1; }
        let start = i;
        while i < s.len && !is_space(s[i]) { i += 1; }
        if i > start { F(s[start..i]); }
    }
}

// The parts with sep between them, appended to out; T any u8 array or slice type.
fn join<T>(out: u8[>..]&, parts: T[:], sep: u8[:]) {
    for p, i in parts {
        if i > 0 { out.append(sep); }
        out.append(p);
    }
}

// s with every occurrence of `old` replaced by `with`, appended to out.
fn format_replaced(out: u8[>..]&, s: u8[:], old: u8[:], with: u8[:]) {
    if old.len == 0 {
        out.append(s);
        return;
    }
    var start = 0;
    var i = 0;
    while i + old.len <= s.len {
        if s[i..i + old.len] == old {
            out.append(s[start..i]);
            out.append(with);
            i += old.len;
            start = i;
        } else {
            i += 1;
        }
    }
    out.append(s[start..]);
}

// F(codepoint) for each UTF-8 sequence; malformed bytes yield 0xFFFD.
fn each_utf8<F>(s: u8[:]) {
    var i = 0;
    while i < s.len {
        let b = s[i] as i64;
        var cp = 0xFFFD;
        var n = 1;
        if b < 0x80 {
            cp = b;
        } else if b >= 0xC0 && b < 0xE0 && i + 1 < s.len {
            cp = ((b & 0x1F) << 6) | ((s[i + 1] as i64) & 0x3F);
            n = 2;
        } else if b >= 0xE0 && b < 0xF0 && i + 2 < s.len {
            cp = ((b & 0x0F) << 12) | (((s[i + 1] as i64) & 0x3F) << 6) |
                 ((s[i + 2] as i64) & 0x3F);
            n = 3;
        } else if b >= 0xF0 && b < 0xF8 && i + 3 < s.len {
            cp = ((b & 0x07) << 18) | (((s[i + 1] as i64) & 0x3F) << 12) |
                 (((s[i + 2] as i64) & 0x3F) << 6) | ((s[i + 3] as i64) & 0x3F);
            n = 4;
        }
        F(cp);
        i += n;
    }
}

// The UTF-8 bytes of a code point.
fn push_utf8(out: u8[>..]&, cp: i64) {
    if cp < 0x80 {
        out.push(cp as u8);
    } else if cp < 0x800 {
        out.push((0xC0 | (cp >> 6)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    } else if cp < 0x10000 {
        out.push((0xE0 | (cp >> 12)) as u8);
        out.push((0x80 | ((cp >> 6) & 0x3F)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    } else {
        out.push((0xF0 | (cp >> 18)) as u8);
        out.push((0x80 | ((cp >> 12) & 0x3F)) as u8);
        out.push((0x80 | ((cp >> 6) & 0x3F)) as u8);
        out.push((0x80 | (cp & 0x3F)) as u8);
    }
}

/stdlib/vec.goose:
// The Goose standard library: `vec` (docs/stdlib.md): small vectors as
// plain structs. Elementwise + - * / are the language's (§6.1); the
// scalar * / broadcast too. The functions here combine components. The int aliases are
// i32 because vectors are data (§3.1), and an i32 component widens into an
// i64 index implicitly.

import math;

struct vec2<T> { x: T, y: T }
struct vec3<T> { x: T, y: T, z: T }
struct vec4<T> { x: T, y: T, z: T, w: T }

type float2 = vec2<f32>;
type float3 = vec3<f32>;
type float4 = vec4<f32>;
type double2 = vec2<f64>;
type double3 = vec3<f64>;
type double4 = vec4<f64>;
type int2 = vec2<i32>;
type int3 = vec3<i32>;
type int4 = vec4<i32>;

let float2_0 = float2 { 0.0, 0.0 };
let float2_1 = float2 { 1.0, 1.0 };
let float3_0 = float3 { 0.0, 0.0, 0.0 };
let float3_1 = float3 { 1.0, 1.0, 1.0 };
let float4_0 = float4 { 0.0, 0.0, 0.0, 0.0 };
let float4_1 = float4 { 1.0, 1.0, 1.0, 1.0 };
let double2_0 = double2 { 0.0, 0.0 };
let double2_1 = double2 { 1.0, 1.0 };
let double3_0 = double3 { 0.0, 0.0, 0.0 };
let double3_1 = double3 { 1.0, 1.0, 1.0 };
let double4_0 = double4 { 0.0, 0.0, 0.0, 0.0 };
let double4_1 = double4 { 1.0, 1.0, 1.0, 1.0 };
let int2_0 = int2 { 0, 0 };
let int2_1 = int2 { 1, 1 };
let int3_0 = int3 { 0, 0, 0 };
let int3_1 = int3 { 1, 1, 1 };
let int4_0 = int4 { 0, 0, 0, 0 };
let int4_1 = int4 { 1, 1, 1, 1 };

fn dot<T>(a: vec2<T>, b: vec2<T>) -> T { a.x * b.x + a.y * b.y }
fn dot<T>(a: vec3<T>, b: vec3<T>) -> T { a.x * b.x + a.y * b.y + a.z * b.z }
fn dot<T>(a: vec4<T>, b: vec4<T>) -> T { a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w }

fn cross<T>(a: vec3<T>, b: vec3<T>) -> vec3<T> {
    vec3<T> { a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x }
}

fn length_sq<T>(v: vec2<T>) -> T { dot(v, v) }
fn length_sq<T>(v: vec3<T>) -> T { dot(v, v) }
fn length_sq<T>(v: vec4<T>) -> T { dot(v, v) }

// Float vectors only: sqrt has f32 and f64 forms.
fn length<T>(v: vec2<T>) -> T { sqrt(length_sq(v)) }
fn length<T>(v: vec3<T>) -> T { sqrt(length_sq(v)) }
fn length<T>(v: vec4<T>) -> T { sqrt(length_sq(v)) }

fn normalize<T>(v: vec2<T>) -> vec2<T> { v / length(v) }
fn normalize<T>(v: vec3<T>) -> vec3<T> { v / length(v) }
fn normalize<T>(v: vec4<T>) -> vec4<T> { v / length(v) }

fn distance<T>(a: vec2<T>, b: vec2<T>) -> T { length(a - b) }
fn distance<T>(a: vec3<T>, b: vec3<T>) -> T { length(a - b) }
fn distance<T>(a: vec4<T>, b: vec4<T>) -> T { length(a - b) }

fn lerp<T>(a: vec2<T>, b: vec2<T>, t: T) -> vec2<T> {
    vec2<T> { a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t }
}
fn lerp<T>(a: vec3<T>, b: vec3<T>, t: T) -> vec3<T> {
    vec3<T> { a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t, a.z + (b.z - a.z) * t }
}
fn lerp<T>(a: vec4<T>, b: vec4<T>, t: T) -> vec4<T> {
    vec4<T> { a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t, a.z + (b.z - a.z) * t,
              a.w + (b.w - a.w) * t }
}

fn xy<T>(v: vec3<T>) -> vec2<T> { vec2<T> { v.x, v.y } }
fn xy<T>(v: vec4<T>) -> vec2<T> { vec2<T> { v.x, v.y } }
fn xyz<T>(v: vec4<T>) -> vec3<T> { vec3<T> { v.x, v.y, v.z } }

/samples/01_tour.goose:
// A tour of the core language in one linear program: values and their
// widths, the array family, slices, structs, control flow as expressions,
// functions with several results, optionals and references. The other
// samples assume what this one shows.
//
// Build and run (from this directory):
//   goose -o tour.c 01_tour.goose && cl tour.c && tour

// A function taking a slice accepts every array kind and any sub-range of
// one, without a copy: the slice is a reference to the elements plus a count.
fn total(xs: i64[:]) -> i64 {
    var t = 0;
    for x in xs { t += x; }
    return t;
}

// Several results are a calling convention, not a tuple type. By custom a
// trailing bool (or error code) says whether the rest is meaningful.
fn divide(a: i64, b: i64) -> i64, bool {
    if b == 0 { return 0, false; }
    return a / b, true;
}

// "Maybe an element": an optional is a nullable reference into the input.
fn first_at_least(xs: i64[:], min: i64) -> i64? {
    for &x in xs { if x >= min { return x; } }
    return null;
}

// Untyped parameters make a function generic; each call instantiates it for
// the argument types it gets.
fn larger(a, b) { if a > b { a } else { b } }

// A struct is packed data in declaration order. Fields may carry defaults,
// which a literal can then leave out.
struct Point { x: f64, y: f64 }
struct Player { name: u8[..16], pos: Point, hp: i32 = 100, alive: bool = true }

fn main() {
    // --- scalars -----------------------------------------------------------
    // `let` binds a constant, `var` a variable. An integer literal adapts to
    // the type it meets; on its own it is an i64, the default for counts and
    // indices. The sized types are for data.
    let answer = 42;
    var count: i32 = 0;
    let byte: u8 = 255;
    let ratio = 0.75;
    let single: f32 = 1.5;
    let yes = 3 > 2;
    count += 1;
    count++;
    print("answer=", answer, " count=", count, " byte=", byte, " ratio=", ratio,
          " single=", single, " yes=", yes);

    // Arithmetic runs at the operands' own width: u8 + u8 is an 8-bit add.
    // A narrower type widens into a wider one implicitly; nothing narrows
    // without a cast.
    let wrapped: u8 = byte + 1;          // unsigned math wraps by definition
    let widened = byte + answer;         // the u8 widens into the i64
    let narrowed = answer as u8;         // range-checked in debug, truncates in release
    print(wrapped, " ", widened, " ", narrowed);
    // `%` is Euclidean, so the result is never negative: `x % n` is always
    // a valid index into an array of length n, whatever the sign of x.
    print(-7 % 3, " ", 7 % -3);

    // --- the array family --------------------------------------------------
    // Every array is inline, packed element data; the kinds differ in how
    // the size behaves. A fixed array has a constant size and no metadata.
    var fixed: i32[4] = [1, 2, 3, 4];
    fixed[0] = 10;
    let zeros: f64[8] = [0.0; 8];        // fill form
    // The grow-only array is the workhorse: a push is a pointer bump on the
    // data stack, nothing is ever moved or reallocated, and references into
    // it stay valid as it grows -- the promise a vector<T> cannot make, and
    // the one the data-structure samples build on.
    var grow: i64[>..] = [];
    for i in 5 { grow.push(i * i); }
    // A grow-shrink array also pops: the natural stack and queue.
    var stack: i64[>..<] = [];
    stack.push(1); stack.push(2); stack.push(3);
    let top = stack.pop();
    // A limited array has a fixed capacity, so it lives inline anywhere a
    // fixed value can: in a struct, as an array element, in a local.
    var small: u8[..8] = [];
    small.push('h'); small.push('i');
    // A variable array is sized at construction and frozen afterwards.
    let frozen: i64[] = [7, 8, 9];
    print(fixed, " ", zeros.len, " ", grow, " ", stack, " ", top, " ",
          small, " ", small.len, "/", small.cap, " ", frozen);

    // A string is a u8 array: no string type, no allocation. A literal is
    // static data, a builder is a growable u8 array, and `format`, `str`
    // and `print` render anything as text into one of those.
    var s: u8[>..] = [];
    s.append("hello");
    s.push(' ');
    format(s, "x", 1, " ", 2.5);
    print(s, " (", s.len, " bytes)");

    // --- slices ------------------------------------------------------------
    // `a[x..y]` is a view of elements x up to y; `^k` counts from the end.
    // A slice cannot dangle: the checker ties it to the array that owns the
    // elements, and that array cannot shrink under it.
    let middle = grow[1..4];
    let last_two = grow[^2..];
    print(middle, " ", last_two, " ", total(middle), " ", total(grow), " ", total(fixed_sum(fixed)));

    // --- structs -----------------------------------------------------------
    // A Player is one flat value: the name's bytes live inside it, not behind
    // a pointer, so an array of players is one contiguous block.
    var p = Player { name: "gus", pos: Point { 1.0, 2.0 } };
    p.hp -= 30;
    p.pos = p.pos + Point { 0.5, 0.5 };  // arithmetic is elementwise on same-typed structs
    print(p);
    print(p.name, " at ", p.pos.x, ",", p.pos.y, " hp ", p.hp);

    // --- control flow as expressions ---------------------------------------
    // `if` and `match` are expressions: no ternary, no temporary assigned in
    // each branch.
    let kind = if p.hp > 50 { "healthy" } else { "hurt" };
    let level = match p.hp { 0 => "dead", 1..50 => "low", _ => "fine" };
    print(kind, " ", level);
    // `guard` states what the code after it relies on; its else must leave.
    // `block` gives `break` a target, so a chain of checks can bail out with
    // a value without a loop.
    let verdict = block {
        guard p.alive else { break "gone"; }
        guard p.hp > 0 else { break "dead"; }
        "standing"
    };
    print(verdict);

    // --- loops -------------------------------------------------------------
    var acc = 0;
    for i in 3 { acc += i; }             // 0, 1, 2
    for i in 10..13 { acc += i; }        // 10, 11, 12
    for x in fixed { acc += x; }         // copies of the elements
    for &x in fixed { x *= 2; }          // references: the mutation form
    for x, i in frozen { acc += x * i; } // with the index
    var n = 0;
    while n < 3 { n++; }
    loop { n--; if n == 0 { break; } }
    print(acc, " ", fixed, " ", n);

    // --- several results, optionals, references ----------------------------
    // Two results come back together, as part of the calling convention:
    // no tuple type, nothing packed and unpacked.
    let q, ok = divide(7, 2);
    let q2, ok2 = divide(1, 0);
    print(q, " ", ok, " ", q2, " ", ok2);
    // An optional must be narrowed before use: inside the `if` it is a plain
    // reference to the element it found.
    let big = first_at_least(grow, 5);
    if big { print("first >= 5 is ", big); } else { print("none"); }
    let none = first_at_least(grow, 100);
    print(none == null);
    // A reference reads and writes as its target; `.=` binds it (where `=`
    // would copy the element) and retargets it, and `.==` asks whether two
    // references name the same target.
    var r .= grow[0];
    r = 100;
    r .= grow[1];
    r += 1;
    print(grow, " ", grow.index_of(r), " ", r .== grow[1]);
    print(larger(3, 9), " ", larger(2.5, 1.5));
}

// A fixed i32 array widened into an i64 array, so `total` can take it: the
// slice type names the element type exactly, and i32 is not i64.
fn fixed_sum(xs: i32[4]) -> i64[4] {
    return [xs[0], xs[1], xs[2], xs[3]];
}

/samples/02_memory.goose:
// Where values live, and what that buys. Goose has no allocator: every
// dynamic value is owned by a variable and lives on a data stack, growth is
// a pointer bump, and the only "free" is a scope ending. This program walks
// through the consequences one at a time, with the numbers to show for it.
//
// Build and run (from this directory):
//   goose -o memory.c 02_memory.goose && cl memory.c && memory

import std;

struct Item { id: i32, weight: f32 }

// A limited array is fixed-size storage with a length: capacity inline,
// no pointer, so a struct holding one is still one flat value.
struct Row { label: u8[..12], cells: i32[..8] }

fn reset(buf: u8[>..]&) { buf.clear(); }

fn main() {
    // 1. A grow-only array never moves its elements. A reference taken
    //    early stays valid however much is pushed afterwards, which is what
    //    a vector<T> or Vec<T> cannot promise: they reallocate.
    var items: Item[>..] = [];
    let first: Item& = items.push(Item { 1, 0.5 });
    for i in 2..100001 { items.push(Item { i as i32, i * 0.5 }); }
    first.weight = 99.5;                 // through the reference, 100000 pushes later
    print(items.len, " items, first weight ", items[0].weight);

    // 2. Scope exit is the free. A buffer declared in a loop body is fresh
    //    each iteration and gone at the closing brace: the data stack's top
    //    is reset to where it was, no destructor runs, no list is walked.
    for round in 3 {
        var scratch: u8[>..] = [];
        for i in 10000 { scratch.push((i % 256) as! u8); }
        print("round ", round, ": ", scratch.len, " bytes of scratch");
    }

    // 3. Or keep one buffer and clear it. A grow-only array may shrink at
    //    a point where nothing in scope refers into it -- the compiler
    //    knows every place a reference into it was stored, and names the
    //    holder if one is live -- so a reused line buffer costs nothing
    //    per line, here through a helper that clears its argument.
    var line: u8[>..] = [];
    for i in 3 {
        reset(line);
        format(line, "line ", i + 1, " of 3");
        print(line);
    }

    // 4. Nested containers stay flat. An array of strings is one block:
    //    lengths and bytes back to back, no pointer per string, where a
    //    vector<string> is an allocation per element. Dropping it is the
    //    same pointer reset as dropping an array of integers.
    var words: u8[][>..] = [];
    for i in 5 { words.push(str("word", i)); }   // built straight into the element
    var bytes = 0;
    for w in words { bytes += w.len; }
    print(words.len, " words, ", bytes, " bytes of text, ", words.len * 4 + bytes,
          " bytes in total (4-byte lengths)");

    // 5. Fixed-size values are copied on assignment; a resizable is not
    //    copied unless the program says so, because that copy is O(n).
    var a: i64[>..] = [1, 2, 3];
    var b = copy(a);
    b.push(4);
    var item2 = items[1];                // a copy: Item is fixed-size
    item2.weight = 0.0;
    print(a, " ", b, " ", items[1].weight);

    // 6. A grow-shrink array pops as well: the natural stack, queue and
    //    scratch heap. References into it live in variables only, so a pop
    //    can never leave a stored reference behind.
    var stack: i64[>..<] = [];
    for i in 5 { stack.push(i * 10); }
    var popped = 0;
    while stack.len > 2 { popped += stack.pop(); }
    print(stack, " popped ", popped);

    // 7. Limited arrays live inline: a struct with two of them is one flat
    //    value with a fixed size, so an array of them is indexable and every
    //    row is next to the previous one in memory.
    var rows: Row[>..] = [];
    for r in 3 {
        var row = Row { label: "row", cells: [] };
        format(row.label, r);
        for c in r + 1 { row.cells.push((r * 10 + c) as i32); }
        rows.push(row);
    }
    for row in rows { print(row.label, ": ", row.cells, " (", row.cells.len, "/", row.cells.cap, ")"); }

    // 8. When lifetimes really are not nested -- a cache, a mutable graph --
    //    a `reusable` pool keeps a freelist of slots. Every slot stays a
    //    valid Item forever, so a stale reference can read a wrong value but
    //    never corrupt memory; that is the whole extent of unsafety.
    reusable var pool: Item[>..] = [];
    let s0 = pool.alloc_index(Item { 10, 1.0 });
    let s1 = pool.alloc_index(Item { 11, 1.0 });
    pool.free(s0);
    let s2 = pool.alloc_index(Item { 12, 2.0 });   // takes slot s0 back
    print("slots ", s0, " ", s1, " ", s2, ", pool length ", pool.len);
    let node: Item& = pool.alloc_ref(Item { 13, 3.0 });
    pool.free(pool.index_of(node));                // a reference turned back into its slot
    print("pool length ", pool.len);
}

/samples/03_strings.goose:
// Strings. There is no string type: a string is any u8 array, a string
// literal is static bytes, a builder is a growable u8 array, and a "view"
// into text is a u8 slice that the checker keeps from dangling. This
// program does the usual things -- build, search, split, parse, format --
// and never copies a byte it does not have to.
//
// Build and run (from this directory):
//   goose -o strings.c 03_strings.goose && cl strings.c && strings

import std;

// A struct with an inline small string: no pointer, no allocation, and a
// `format` overload so print/str/format render it the way it wants.
struct Person { name: u8[..16], age: i32 }

fn format(out: u8[>..]&, p: Person) {
    format(out, p.name, " (", p.age, ")");
}

fn main() {
    // --- building ----------------------------------------------------------
    // A builder is a grow-only byte array on the data stack: appending is a
    // pointer bump, nothing is reallocated, and it goes away with the scope.
    var s: u8[>..] = [];                 // the builder: append, push, format
    s.append("Hello");
    s.push(',');
    s.push(' ');
    format(s, "world! ", 6 * 7, " ", 2.5);
    print(s, " [", s.len, " bytes]");
    let joined = str("pi=", 3.14159, " e=", 2.71828);   // a fresh string, built straight into joined
    print(joined);
    // Padded and based numbers, fixed decimals.
    var t: u8[>..] = [];
    format_int(t, 255, 16, 4, '0'); t.push(' ');
    format_int(t, 255, 2, 10, ' '); t.push(' ');
    format_flt(t, 2.0 / 3.0, 3);
    print(t);

    // --- views into text ---------------------------------------------------
    // A slice is a reference plus a length: `line[a..b]` is the text between
    // a and b, no copy. trim/split/find return slices into the input.
    let line = "  key = some value  ";
    let body = trim(line);
    let eq = find(body, "=");
    let key = trim(body[..eq]);
    let value = trim(body[eq + 1..]);
    print("'", body, "' -> '", key, "' / '", value, "'");
    print(starts_with(body, "key"), " ", ends_with(body, "value"), " ", find(body, "zzz"));

    // --- splitting -----------------------------------------------------------
    // split returns an array of slices into its input: a few bytes per part
    // and no text copied, where most languages hand back a list of strings.
    let csv = "alice,30,paris,,bob,25";
    let parts = split(csv, ',');         // an array of slices, all into csv
    print(parts.len, " parts: ", parts);
    var upper: u8[>..] = [];
    each_split("one two  three", ' ') {  // no array built: a block per part
        if it.len > 0 {
            upper.append(it);
            to_upper(upper[^it.len..]);  // in place, on the copy just appended
            upper.push('|');
        }
    };
    print(upper);
    var out: u8[>..] = [];
    join(out, parts, " | ");
    print(out);

    // --- parsing -------------------------------------------------------------
    for p in parts {
        let v, ok = parse_int(p);
        if ok { print("  number ", v); } else { print("  text '", p, "'"); }
    }
    let f, fok = parse_flt("-2.5e3");
    print(f, " ", fok);
    let h, hok = parse_int("ff", 16);
    print(h, " ", hok);

    // --- comparing and sorting -------------------------------------------
    // An array of variable-size strings cannot be sorted in place (its
    // elements are not all the same size), but an array of slices into it
    // can, and that sorts the strings without moving a byte of text.
    var names: u8[][>..] = [];
    names.push("delta"); names.push("alpha"); names.push("charlie"); names.push("bravo");
    var views: u8[:][>..] = [];
    for n in names { views.push(n[..]); }
    sort(views) { a, b => compare(a, b) < 0 };
    print(views);
    print(compare("abc", "abd"), " ", compare("b", "a"), " ", "abc" == "abc");

    // --- replacing, case -------------------------------------------------
    var r: u8[>..] = [];
    format_replaced(r, "the cat sat on the mat", "at", "og");
    print(r);
    var lower: u8[>..] = [];
    lower.append("MiXeD Case");
    to_lower(lower);
    print(lower);

    // --- bytes and code points -------------------------------------------
    // Text is bytes; UTF-8 is a convention the library understands.
    let greek = "αβγ";
    print(greek.len, " bytes, ", greek[0], " first byte");
    var cps = 0;
    each_utf8(greek) { cps++; };
    var back: u8[>..] = [];
    each_utf8(greek) { push_utf8(back, it + 1); };   // the next letter each
    print(cps, " code points; shifted: ", back);
    // A byte is a number: print shows 97, and it takes a push to append one.
    var caps: u8[>..] = [];
    for c in "abc" { caps.push(c - 'a' + 'A'); }
    print("abc"[0], " ", caps, " ", str('a'));

    // --- inline strings in structs -----------------------------------------
    // A Person is one flat value: the name's bytes live in the struct, so an
    // array of them is a single block, sortable and copyable as plain data.
    var people: Person[>..] = [];
    people.push(Person { name: "ada", age: 36 });
    people.push(Person { name: "grace", age: 45 });
    var p2 = Person { name: "", age: 20 };
    format(p2.name, "linus");            // a limited array is a builder too, up to its capacity
    people.push(p2);
    print(people);
    for &p in people { p.age += 1; }
    print(str(people[0]), " ", people[2].name.len, "/", people[2].name.cap);
}

/samples/04_errors.goose:
// Error handling. Goose has no exceptions and no Result type; it has three
// idioms, and this program uses each where it fits: a trailing bool (or
// code) for a two-outcome call, an optional for "found or not", and
// `return ... from` for a failure deep inside nested calls that should land
// in one place. Plus the ones that end the program: assert and abort.
//
// Build and run (from this directory):
//   goose -o errors.c 04_errors.goose && cl errors.c && errors

import std;

struct User { name: u8[..16], age: i32 }

// 1. A trailing bool: the caller writes `let v, ok = ...` and tests ok.
fn parse_age(s: u8[:]) -> i32, bool {
    let v, ok = parse_int(trim(s));
    if !ok || v < 0 || v > 150 { return 0, false; }
    return v as i32, true;
}

// 2. An optional: a reference to the element, or null. The caller must
//    narrow it with if/guard before touching it.
fn find_user(users: User[:], name: u8[:]) -> User? {
    for &u in users { if u.name == name { return u; } }
    return null;
}

// 3. return-from: any failure inside the nested parsing below returns from
//    `load` directly, unwinding parse_record and parse_field with it. Those
//    two return plain values and carry no error type, and the happy path
//    pays nothing for the possibility. The error is the last result, by
//    convention; "" means none.
fn load(text: u8[:]) -> User[>..], u8[] {
    var users: User[>..] = [];
    var lineno = 0;
    each_split(text, '\n') {
        lineno++;
        if it.len > 0 { users.push(parse_record(it, lineno)); }   // built straight into the element
    };
    return users, "";
}

fn parse_record(line: u8[:], lineno: i64) -> User {
    let comma = find(line, ",");
    guard comma >= 0 else { return [], str("line ", lineno, ": expected name,age") from load; }
    let name = parse_field(line[..comma], lineno);
    let age, ok = parse_age(line[comma + 1..]);
    guard ok else { return [], str("line ", lineno, ": bad age '", trim(line[comma + 1..]), "'") from load; }
    return User { name: name, age: age };
}

fn parse_field(s: u8[:], lineno: i64) -> u8[..16] {
    let t = trim(s);
    guard t.len > 0 else { return [], str("line ", lineno, ": empty name") from load; }
    guard t.len <= 16 else { return [], str("line ", lineno, ": name too long") from load; }
    return t;
}

fn report(text: u8[:]) {
    let users, err = load(text);
    if err.len > 0 { print("error: ", err); return; }
    print("loaded ", users.len, " users");
    for u in users { print("  ", u.name, " ", u.age); }
}

fn main() {
    // A two-outcome call, tested inline.
    for s in ["42", " 7 ", "-3", "abc", "200"] {
        let age, ok = parse_age(s);
        if ok { print("'", s, "' -> ", age); } else { print("'", s, "' is not an age"); }
    }

    // An optional, narrowed by `if` and by `guard`.
    var users: User[>..] = [];
    users.push(User { name: "ada", age: 36 });
    users.push(User { name: "linus", age: 20 });
    let found = find_user(users, "linus");
    if found { print("found ", found.name, ", age ", found.age); }
    let missing = find_user(users, "nobody");
    if missing == null { print("nobody is not a user"); }
    block {
        let u = find_user(users, "ada");
        guard u else { print("no ada"); break; }
        u.age += 1;                      // narrowed: a plain reference here
        print("ada is now ", u.age);
    }

    // Deep failures landing in one place.
    report("ada, 36\nlinus, 20\n");
    report("ada, 36\nlinus\n");
    report("ada, 36\n, 20\n");
    report("ada, x\n");
    report("averyveryverylongname, 1\n");

    // The ones that stop the program: assert for invariants, abort for a
    // fatal condition with a message, exit for a deliberate end with a code.
    // None of them fire here.
    assert(users.len == 2);
    if users.len > 100 { abort("too many users"); }
    if users.len == 0 { exit(1); }
    print("done");
}

/samples/05_shapes.goose:
// Algebraic data types, the only dynamic polymorphism in the language: no
// inheritance, no vtables. The classic shapes example, with the two things
// that make Goose's version different -- an enum value can be stored
// *fixed* (every value the size of the largest variant, indexable and
// overwritable) or *variable* (each value exactly its variant's size, text
// included, walked sequentially or reached through an index kept beside the
// array) -- and case functions, which are `match` written as an overload
// set: the virtual-call idiom.
//
// Build and run (from this directory):
//   goose -o shapes.c 05_shapes.goose && cl shapes.c && shapes

import math;

enum Shape {
    Circle { r: f64 },
    Rect { w: f64, h: f64 },
    Tri { a: f64, b: f64, c: f64 },
    Dot,
}

// Case functions: one overload per variant, called with the enum value.
// The call dispatches on the tag; the checker requires every variant to
// have exactly one applicable overload, so a new variant is a compile error
// here until it gets its case.
fn area(s: Shape.Circle) -> f64 { PI * s.r * s.r }
fn area(s: Shape.Rect) -> f64 { s.w * s.h }
fn area(s: Shape.Tri) -> f64 {
    let p = (s.a + s.b + s.c) / 2.0;     // Heron's formula
    sqrt(p * (p - s.a) * (p - s.b) * (p - s.c))
}
fn area(s: Shape.Dot) -> f64 { 0.0 }

fn sides(s: Shape.Circle) -> i64 { 0 }
fn sides(s: Shape.Rect) -> i64 { 4 }
fn sides(s: Shape.Tri) -> i64 { 3 }
fn sides(s: Shape.Dot) -> i64 { 0 }

// `match` is the inline form; `_` covers the rest.
fn name(s: Shape) -> u8[:] {
    match s {
        Circle c => "circle",
        Rect r => if r.w == r.h { "square" } else { "rectangle" },
        _ => "other",
    }
}

// Scaling a fixed-mode value in place: the whole value is replaced, which
// is allowed exactly because nothing can point inside a fixed-mode payload.
fn scaled(s: Shape, k: f64) -> Shape {
    match s {
        Circle c => Shape.Circle { r: c.r * k },
        Rect r => Shape.Rect { w: r.w * k, h: r.h * k },
        Tri t => Shape.Tri { a: t.a * k, b: t.b * k, c: t.c * k },
        Dot => Shape.Dot,
    }
}

// A drawing's marks: shapes, and labels with text. A Label holds its text
// itself, a varint length and then the bytes, right after the tag, so the
// marks in a variable-mode array are one flat run of bytes, strings
// included, with no pointer anywhere. (An enum in Rust or C++ has one fixed
// size: its string variant would be a fixed-size string object, and every
// element would be as big as the largest variant.) The text makes Mark a
// variable-size type, so it is only ever stored in variable mode.
enum Mark {
    Circle { r: f64 },
    Rect { w: f64, h: f64 },
    Label { text: u8[varint] },
    Dot,
}

// Packed marks have no fixed stride, so `marks` cannot be indexed, but an
// index beside it can be: each entry is one mark's offset from the base of
// `marks` (`in marks`, 4 bytes), and loading one is an add. The array such
// offsets are measured from is a global; a local array can be indexed the
// same way with plain 8-byte references, `(Mark..&)[>..]`.
var marks: Mark..[>..] = [];
var mark_at: (Mark..&<u32 in marks>)[>..] = [];

fn main() {
    // --- fixed mode: an ordinary array of enum values ----------------------
    // Each element is 1 tag byte + the largest payload (three f64s): 25 bytes,
    // the layout a Rust enum or a C++ variant also has; `match` reads the
    // payload in place, with no boxing and no virtual call.
    var shapes: Shape[>..] = [];
    shapes.push(Shape.Circle { r: 1.0 });
    shapes.push(Shape.Rect { w: 2.0, h: 3.0 });
    shapes.push(Shape.Tri { a: 3.0, b: 4.0, c: 5.0 });
    shapes.push(Shape.Dot);
    shapes.push(Shape.Rect { w: 2.0, h: 2.0 });
    var total = 0.0;
    for s in shapes {
        print(name(s), " ", s, " area ", area(s), " sides ", sides(s));
        total += area(s);
    }
    print("total area ", total);
    // Indexable and replaceable: element 3 becomes a different variant.
    shapes[3] = Shape.Circle { r: 0.5 };
    for &s in shapes { s = scaled(s, 2.0); }
    print(shapes);

    // --- variable mode: each element as big as its own variant -------------
    // A Dot is 1 byte, a Circle 9, a Rect 17: half the memory of the fixed
    // array for this mix. The price is sequential access: no indexing (short
    // of keeping an index, below), and an element can never change variant,
    // since its neighbors are packed right behind it. In exchange, references
    // into a payload are allowed.
    var packed: Shape..[>..] = [];
    packed.push(Shape.Circle { r: 1.0 });
    packed.push(Shape.Dot);
    packed.push(Shape.Rect { w: 2.0, h: 3.0 });
    packed.push(Shape.Dot);
    packed.push(Shape.Tri { a: 3.0, b: 4.0, c: 5.0 });
    var dots = 0;
    var widest = 0.0;
    for s in packed {                    // variable-size elements bind by reference
        match s {
            Dot => block { dots++; },
            Rect &r => block { r.w += 1.0; widest = r.w; },   // edits the payload in place, inside the array
            _ => block {},
        }
        print(name(s), " ", area(s));
    }
    print(dots, " dots, widest rect now ", widest);
    print(packed);

    // --- variable mode with an index: random access ------------------------
    // push builds each mark in place at the end of `marks` and returns a
    // reference to it, which the index keeps as that mark's offset.
    mark_at.push(marks.push(Mark.Label { text: "hello, goose" }));
    mark_at.push(marks.push(Mark.Circle { r: 1.5 }));
    mark_at.push(marks.push(Mark.Dot));
    mark_at.push(marks.push(Mark.Rect { w: 2.0, h: 3.0 }));
    mark_at.push(marks.push(Mark.Label { text: "x" }));
    for i in [3, 0, 4, 1, 2] {           // any order; each lookup is one add
        match mark_at[i] {
            Circle c => print(i, ": circle ", c.r),
            Rect r => print(i, ": rect ", r.w, " by ", r.h),
            Label l => print(i, ": label \"", l.text, "\""),
            Dot => print(i, ": dot"),
        }
    }
    // A Label is its tag, a 1-byte length and its text: 14 + 9 + 1 + 17 + 3.
    print(marks.len, " marks in ", bytes_of(marks).len, " bytes");
}

/samples/06_functions.goose:
// Functions: generics without declaring them, overloading, UFCS, function
// values that compile to plain loops, nested functions that see their
// enclosing locals, and a `return` from inside a block that leaves the
// whole enclosing function. Everything here is resolved at compile time;
// there are no function pointers and nothing is boxed.
//
// Build and run (from this directory):
//   goose -o functions.c 06_functions.goose && cl functions.c && functions

import std;

// An untyped parameter is a generic one: the function is compiled once per
// argument type it is called with.
fn twice(x) { x + x }

// Explicit type parameters say that two arguments must agree.
fn span<T>(a: T, b: T) -> T { if a > b { a - b } else { b - a } }

// Overloads resolve on the argument types; a slice parameter takes any
// array kind, or a sub-range of one.
fn describe(x: i64) -> u8[>..] { str("int ", x) }
fn describe(x: f64) -> u8[>..] { str("float ", x) }
fn describe(xs: i64[:]) -> u8[>..] { str(xs.len, " ints, first ", xs[0]) }

// A higher-order function: F is a function value, a compile-time parameter.
// Calling F(...) inlines the block; this compiles to the loop it looks like.
fn each_pair<T, F>(xs: T[:]) {
    for i in 0..xs.len - 1 { F(xs[i], xs[i + 1]); }
}

// A HOF may return what its block produces, without saying what that is:
// the block is typechecked at each call, so U is whatever F returns.
fn best_by<T, F>(xs: T[:]) -> T {
    var b = xs[0];
    var bk = F(b);
    for x in xs[1..] {
        let k = F(x);
        if k > bk { b = x; bk = k; }
    }
    return b;
}

// A HOF that stops early: the block may `return` from the *caller*, which
// gives a hand-written iterator the same power as a for loop.
fn each_step<F>(lo: i64, hi: i64, step: i64) {
    var i = lo;
    while i < hi { F(i); i += step; }
}

struct Employee { name: u8[..12], dept: u8[..8], salary: i32 }

// The function that `return`s through each_step.
fn first_multiple_of_7(lo: i64, hi: i64) -> i64 {
    each_step(lo, hi, 3) { if it % 7 == 0 { return it; } };
    return -1;
}

fn main() {
    print(twice(21), " ", twice(1.5), " ", span(3, 8), " ", span(2.5, 1.0));
    var xs: i64[>..] = [4, 8, 15, 16, 23, 42];
    // UFCS: x.f(a) is f(x, a), for any function.
    print(describe(7), "; ", 2.5.describe(), "; ", xs.describe(), "; ", describe(xs[2..]));
    print(twice(3).describe());

    // Blocks: the implicit `it`, or named parameters. No allocation, no
    // indirect call: each one is compiled into its caller.
    var gaps: i64[>..] = [];
    each_pair(xs) { a, b => gaps.push(b - a); };   // writes an enclosing local
    print("gaps ", gaps);
    print("biggest gap ", max(gaps), " at ", max_by(gaps) { it });
    print(first_multiple_of_7(10, 40), " ", first_multiple_of_7(10, 12));

    // The standard library is written this way too. filter and map build
    // their result straight into the variable receiving it: no intermediate
    // array, no allocation, and the block is inlined into their loop.
    let evens = xs.filter() { it % 2 == 0 };
    let squares = xs.map() { it * it };
    let total = fold(xs, 0) { acc, x => acc + x };
    print(evens, " ", squares, " ", total, " ", xs.any() { it > 40 }, " ", xs.count() { it < 10 });

    var staff: Employee[>..] = [];
    staff.push(Employee { name: "ada", dept: "eng", salary: 120 });
    staff.push(Employee { name: "grace", dept: "eng", salary: 135 });
    staff.push(Employee { name: "linus", dept: "ops", salary: 90 });
    staff.push(Employee { name: "ken", dept: "ops", salary: 95 });
    let top = best_by(staff) { it.salary };
    print("top earner ", top.name);
    sort(staff) { a, b => a.salary > b.salary };
    for e in staff { print("  ", e.name, " ", e.dept, " ", e.salary); }

    // A nested function reads and writes the locals around it, like a block,
    // and can be called by name more than once.
    var budget = 0;
    var seen = 0;
    fn spend(e: Employee&) {
        budget += e.salary;
        seen++;
    }
    for &e in staff { if e.dept == "eng" { spend(e); } }
    print("eng budget ", budget, " over ", seen, " people");

    // A named function as a value, where a block would be too long.
    fn by_name(a: Employee, b: Employee) -> bool { compare(a.name[..], b.name[..]) < 0 }
    sort(staff, by_name);
    for e in staff { print("  ", e.name); }
}

/samples/07_sieve.goose:
// The sieve of Eratosthenes: the classic tight loop. Everything here runs
// at the width it is declared at -- the flags are bytes, the loop counters
// are i32 -- and the compiler proves every index in range, so the inner
// loop is the same three instructions C would emit, with a bounds check
// nowhere in sight.
//
// Build and run (from this directory):
//   goose -o sieve.c 07_sieve.goose && cl sieve.c && sieve

import std;
import os;

let N = 10000000;

fn main() {
    // One byte per candidate, all "prime" until crossed out: ten million
    // bytes in one block, filled in place by resize.
    var flags: u8[>..] = [];
    flags.resize(N + 1, 1);
    flags[0] = 0;
    flags[1] = 0;
    let t0 = clock();
    var i = 2;
    while i * i <= N {
        if flags[i] == 1 {
            // Cross out the multiples from i*i on: smaller ones were hit
            // by a smaller prime already.
            var j = i * i;
            while j <= N { flags[j] = 0; j += i; }
        }
        i++;
    }
    let t1 = clock();

    // Collect the primes. `%` is Euclidean, so bucketing by residue needs
    // no care about signs; here it counts the primes by their last digit.
    var primes: i32[>..] = [];
    var by_last_digit: i64[10] = [0; 10];
    for n, k in flags {
        if n == 1 {
            primes.push(k as i32);
            by_last_digit[k % 10] += 1;
        }
    }
    // Twin primes: pairs two apart.
    var twins = 0;
    for k in 1..primes.len {
        if primes[k] - primes[k - 1] == 2 { twins++; }
    }
    print(primes.len, " primes up to ", N);
    // Timing goes to stderr, so the output proper stays the same run to run.
    var note: u8[>..] = [];
    format(note, "sieve took ");
    format_flt(note, (t1 - t0) * 1000.0, 1);
    format(note, " ms\n");
    write_stderr(note);
    print("last ten: ", primes[^10..]);
    print("twin pairs: ", twins);
    print("by last digit: ", by_last_digit);
    // A checksum in wrapping unsigned arithmetic, which is what unsigned
    // types mean: no overflow checks, no surprises.
    var h: u32 = 0;
    for p in primes { h = h * 31 + p as u32; }
    print("hash ", h);
}

/samples/08_bignum.goose:
// Arbitrary-precision integers on an array of 32-bit limbs, least
// significant first. Multiplying two limbs needs a 64-bit product and a
// carry, which is exactly the arithmetic Goose's typed integers express:
// `u32 * u32` is a 32-bit multiply, so the code says `as u64` where it
// wants the wide one, and the carries are visible instead of accidental.
// Computes 100!, the 500th Fibonacci number and 2^1000, and prints them in
// decimal with repeated division.
//
// Build and run (from this directory):
//   goose -o bignum.c 08_bignum.goose && cl bignum.c && bignum

import std;

let BASE: u64 = 4294967296;              // 2^32

// A number is its limbs; the value 0 is an empty array. Grow-only is
// enough: normalizing pops leading zero limbs, which a grow-only array
// allows wherever nothing in scope refers into it, and nothing ever points
// into a number. Fresh results are built into whatever receives them, so
// `let f = factorial(100)` allocates nothing on the way.
fn from_int(v: u64) -> u32[>..] {
    var n: u32[>..] = [];
    var x = v;
    while x > 0 { n.push(x as! u32); x = x >> 32; }
    return n;
}

// n = n * m + a, in place: one pass over the limbs with a running carry.
fn mul_add_small(n: u32[>..]&, m: u32, a: u32) {
    var carry = a as u64;
    for &limb in n {
        let t = limb as u64 * m + carry;   // a 64-bit multiply; u32 * u32 would wrap at 32
        limb = t as! u32;                // the low half stays, the rest carries
        carry = t >> 32;
    }
    if carry > 0 { n.push(carry as! u32); }
}

fn add(a: u32[:], b: u32[:]) -> u32[>..] {
    var r: u32[>..] = [];
    var carry: u64 = 0;
    for i in max(a.len, b.len) {
        let x: u64 = if i < a.len { a[i] } else { 0 };
        let y: u64 = if i < b.len { b[i] } else { 0 };
        let t = x + y + carry;
        r.push(t as! u32);
        carry = t >> 32;
    }
    if carry > 0 { r.push(carry as! u32); }
    return r;
}

// Schoolbook multiplication: r[i + j] accumulates a[i] * b[j].
fn mul(a: u32[:], b: u32[:]) -> u32[>..] {
    var r: u32[>..] = [];
    r.resize(a.len + b.len, 0);
    for i in a.len {
        var carry: u64 = 0;
        for j in b.len {
            let t = r[i + j] + a[i] as u64 * b[j] + carry;
            r[i + j] = t as! u32;
            carry = t >> 32;
        }
        r[i + b.len] = carry as! u32;
    }
    while r.len > 0 && r[r.len - 1] == 0 { r.pop(); }   // drop leading zeros
    return r;
}

// n / d in place, returning the remainder: the step decimal printing needs.
// The pop through the reference is checked at each call, against what the
// caller has in scope.
fn div_small(n: u32[>..]&, d: u32) -> u32 {
    var rem: u64 = 0;
    var i = n.len;
    while i > 0 {
        i--;
        let cur = rem << 32 | n[i];
        n[i] = (cur / d) as! u32;
        rem = cur % d;
    }
    while n.len > 0 && n[n.len - 1] == 0 { n.pop(); }
    return rem as! u32;
}

// Decimal text: peel off nine digits at a time from a working copy, then
// reverse the chunks into the output.
fn format(out: u8[>..]&, n: u32[>..]&) {
    if n.len == 0 { out.push('0'); return; }
    var work = copy(n);                  // the one copy, since division consumes its input
    var chunks: u32[>..] = [];           // nine decimal digits per entry, freed with the call
    while work.len > 0 {
        let chunk = div_small(work, 1000000000);
        chunks.push(chunk);
    }
    var first = true;
    each_rev(chunks) { c =>
        if first { format(out, c); first = false; }
        else { format_uint(out, c as u64, 10, 9, '0'); }
    };
}

fn factorial(k: i64) -> u32[>..] {
    var n = from_int(1);
    for i in 2..k + 1 { mul_add_small(n, i as u32, 0); }
    return n;
}

fn fib(k: i64) -> u32[>..] {
    var a = from_int(0);
    var b = from_int(1);
    for i in k {
        let c = add(a, b);
        a = copy(b);
        b = copy(c);
    }
    return a;
}

fn pow2(k: i64) -> u32[>..] {
    var n = from_int(1);
    for i in k { mul_add_small(n, 2, 0); }
    return n;
}

fn digits(n: u32[>..]&) -> i64 { str(n).len }

fn main() {
    let f100 = factorial(100);
    print("100! = ", f100);
    print("  ", f100.len, " limbs, ", digits(f100), " digits");
    let f500 = fib(500);
    print("fib(500) = ", f500);
    let p = pow2(1000);
    print("2^1000 has ", digits(p), " digits and ends in ...", str(p)[^12..]);
    // (2^500)^2 == 2^1000, through the general multiply.
    let h = pow2(500);
    let sq = mul(h, h);
    print("2^500 squared matches: ", sq == p);
    // 100! / (99 * 100) == 98!
    var q = copy(f100);
    div_small(q, 99);
    div_small(q, 100);
    print("100! / 9900 == 98!: ", q == factorial(98));
}

/samples/09_sorting.goose:
// Sorting and searching, written out: insertion sort, a recursive merge
// sort, and binary search, all over slices, so they work on any array kind
// and on any sub-range of one. Then the same jobs through the standard
// library, and timings on a million integers. The merge sort shows the one
// rule recursion has in Goose: a recursive function owns no growable
// locals, so the scratch buffer belongs to the caller and is passed in.
//
// Build and run (from this directory):
//   goose -o sorting.c 09_sorting.goose && cl sorting.c && sorting

import std;
import os;

fn insertion_sort(xs: i32[:]) {
    for i in 1..xs.len {
        let v = xs[i];
        var j = i;
        while j > 0 && xs[j - 1] > v {
            xs[j] = xs[j - 1];
            j--;
        }
        xs[j] = v;
    }
}

// Sorts xs using tmp (at least as long) as scratch. Both halves are
// sub-slices, so no index arithmetic leaks into the merge, and a call costs
// only native stack: nothing is allocated per level.
recursive fn merge_sort(xs: i32[:], tmp: i32[:]) {
    if xs.len <= 16 { insertion_sort(xs); return; }
    let mid = xs.len / 2;
    merge_sort(xs[..mid], tmp[..mid]);
    merge_sort(xs[mid..], tmp[mid..]);
    var i = 0;
    var j = mid;
    var k = 0;
    while i < mid && j < xs.len {
        if xs[j] < xs[i] { tmp[k] = xs[j]; j++; } else { tmp[k] = xs[i]; i++; }
        k++;
    }
    while i < mid { tmp[k] = xs[i]; i++; k++; }
    while j < xs.len { tmp[k] = xs[j]; j++; k++; }
    copy_into(xs, tmp[..xs.len]);
}

// The index of v in a sorted slice, or -1.
fn bsearch(xs: i32[:], v: i32) -> i64 {
    var lo = 0;
    var hi = xs.len;
    while lo < hi {
        let m = (lo + hi) / 2;
        if xs[m] < v { lo = m + 1; } else { hi = m; }
    }
    if lo < xs.len && xs[lo] == v { lo } else { -1 }
}

fn is_sorted(xs: i32[:]) -> bool {
    for i in 1..xs.len { if xs[i - 1] > xs[i] { return false; } }
    return true;
}

fn random_ints(n: i64, seed: u64) -> i32[>..] {
    var r = rng { seed };
    var xs: i32[>..] = [];
    for i in n { xs.push(r.rand_int(1000000) as i32); }
    return xs;
}

fn timed(label: u8[:], t0: f64) {
    var note: u8[>..] = [];
    format(note, label, ": ");
    format_flt(note, (clock() - t0) * 1000.0, 1);
    format(note, " ms\n");
    write_stderr(note);                  // stderr, so stdout stays deterministic
}

struct City { name: u8[..12], pop: i32 }

fn main() {
    // A small array, by hand.
    var small: i32[>..] = [5, 2, 9, 1, 5, 6, 3];
    insertion_sort(small);
    print(small, " ", is_sorted(small));
    print(bsearch(small, 6), " ", bsearch(small, 4), " ", bsearch(small, 1));
    // A sub-range: only the middle five are sorted.
    var part: i32[>..] = [9, 8, 7, 6, 5, 4, 3, 2, 1];
    insertion_sort(part[2..7]);
